#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// 模拟系统参数宏定义
#define VIN         12.0f       // 输入电压 (V)
#define VREF        24.0f       // 参考输出电压 (V)
#define L1          100e-6f     // 电感 L1 (H)
#define L2          100e-6f     // 电感 L2 (H)
#define C1          100e-6f     // 耦合电容 C1 (F)
#define C2          220e-6f     // 输出电容 C2 (F)
#define R_LOAD_INIT 10.0f       // 标称负载电阻 (Ohm)
#define SWITCH_FREQ 100000.0f   // 开关频率 (Hz)
#define TS          (1.0f / SWITCH_FREQ) // 采样周期 (s)

// 滑模控制参数
#define LAMBDA      5000.0f     // 滑模面系数 (指数趋近律参数)
#define EPSILON     0.01f       // 边界层厚度 (防止抖振)
#define K_SMC       0.5f        // 滑模增益

// 模拟ADC读取宏 (mock)
#define ADC_READ_VOUT()   (vout_mock)
#define ADC_READ_IL1()    (il1_mock)
#define ADC_READ_IL2()    (il2_mock)
#define ADC_READ_VC1()    (vc1_mock)

// 全局变量 (模拟系统状态)
static float vout_mock = 0.0f;
static float il1_mock  = 0.0f;
static float il2_mock  = 0.0f;
static float vc1_mock  = 0.0f;
static float r_load    = R_LOAD_INIT; // 可变的负载电阻

// 滑模控制器结构体
typedef struct {
    float vout_ref;      // 输出电压参考
    float vout;          // 当前输出电压
    float il1;           // 电感L1电流
    float il2;           // 电感L2电流
    float vc1;           // 耦合电容电压
    float duty;          // 占空比输出 (0~1)
    float sliding_surface; // 滑模面值
} SEPIC_SMC_Controller;

// 初始化控制器
void SEPIC_SMC_Init(SEPIC_SMC_Controller *ctrl) {
    ctrl->vout_ref = VREF;
    ctrl->vout     = 0.0f;
    ctrl->il1      = 0.0f;
    ctrl->il2      = 0.0f;
    ctrl->vc1      = 0.0f;
    ctrl->duty     = 0.0f;
    ctrl->sliding_surface = 0.0f;
}

// 滑模控制更新 (指数趋近律)
void SEPIC_SMC_Update(SEPIC_SMC_Controller *ctrl) {
    // 读取ADC模拟值
    ctrl->vout = ADC_READ_VOUT();
    ctrl->il1  = ADC_READ_IL1();
    ctrl->il2  = ADC_READ_IL2();
    ctrl->vc1  = ADC_READ_VC1();

    // 计算误差
    float err_v = ctrl->vout_ref - ctrl->vout;

    // 滑模面设计: s = lambda * err_v + (il1 + il2)  (简化模型)
    // 实际SEPIC滑模面通常包含电压误差和电流信息
    ctrl->sliding_surface = LAMBDA * err_v + (ctrl->il1 + ctrl->il2);

    // 指数趋近律: s_dot = -epsilon * sign(s) - k * s
    float sign_s = (ctrl->sliding_surface > 0.0f) ? 1.0f : 
                   (ctrl->sliding_surface < 0.0f) ? -1.0f : 0.0f;
    float s_dot = -EPSILON * sign_s - K_SMC * ctrl->sliding_surface;

    // 等效控制推导 (简化: 占空比直接由滑模面动态决定)
    // 实际需根据SEPIC模型推导，此处使用近似公式
    float duty_candidate = 0.5f + 0.1f * s_dot; // 简化映射
    if (duty_candidate > 0.95f) duty_candidate = 0.95f;
    if (duty_candidate < 0.05f) duty_candidate = 0.05f;
    ctrl->duty = duty_candidate;
}

// 模拟系统动态 (简单欧拉法)
void System_Simulate(SEPIC_SMC_Controller *ctrl, float dt) {
    // 简化SEPIC状态方程 (连续时间模型)
    float d = ctrl->duty;
    float vout = ctrl->vout;
    float il1  = ctrl->il1;
    float il2  = ctrl->il2;
    float vc1  = ctrl->vc1;
    float vin  = VIN;
    float r    = r_load; // 使用全局可变负载

    // 状态导数 (忽略寄生参数)
    float dil1_dt = (vin - (1-d)*vc1 - (1-d)*vout) / L1;
    float dil2_dt = (d*vc1 - (1-d)*vout) / L2;
    float dvc1_dt = ((1-d)*il1 - d*il2) / C1;
    float dvout_dt = ((1-d)*(il1+il2) - vout/r) / C2;

    // 欧拉积分
    il1_mock  += dil1_dt * dt;
    il2_mock  += dil2_dt * dt;
    vc1_mock  += dvc1_dt * dt;
    vout_mock += dvout_dt * dt;

    // 限制状态 (防止发散)
    if (il1_mock < 0) il1_mock = 0;
    if (il2_mock < 0) il2_mock = 0;
    if (vout_mock < 0) vout_mock = 0;
    if (vc1_mock < 0) vc1_mock = 0;
}

int main() {
    SEPIC_SMC_Controller controller;
    SEPIC_SMC_Init(&controller);

    printf("SEPIC 滑模控制仿真 (指数趋近律, 抗负载扰动)\n");
    printf("参考电压: %.2f V, 输入电压: %.2f V\n", VREF, VIN);
    printf("时间(s)\tVout(V)\tIL1(A)\tIL2(A)\tDuty\n");

    // 仿真 0.1 秒
    float time = 0.0f;
    int steps = 10000;
    float dt = 0.1f / steps;

    // 负载扰动模拟: 在0.05秒时负载突变
    float load_change_time = 0.05f;

    for (int i = 0; i < steps; i++) {
        // 负载扰动注入 (模拟抗扰)
        if (fabs(time - load_change_time) < dt) {
            r_load = 5.0f;  // 负载减半 (扰动)
            printf("*** 负载扰动: R_LOAD = %.1f Ohm ***\n", r_load);
        }

        // 更新控制器
        SEPIC_SMC_Update(&controller);

        // 模拟系统动态
        System_Simulate(&controller, dt);

        // 打印每100步
        if (i % 100 == 0) {
            printf("%.4f\t%.3f\t%.3f\t%.3f\t%.3f\n", 
                   time, vout_mock, il1_mock, il2_mock, controller.duty);
        }

        time += dt;
    }

    // 恢复负载
    r_load = 10.0f;
    printf("\n仿真结束, 最终输出电压: %.3f V\n", vout_mock);
    return 0;
}
