#include <stdlib.h>

// ==================== 宏定义（Mock 寄存器） ====================
#define PWM_DUTY_MAX     1000
#define ADC_REF_VOLTAGE   3.3f
#define ADC_RESOLUTION    4095.0f

// 模拟 ADC 寄存器
static volatile uint16_t mock_adc_current_raw = 0;

// 模拟 PWM 占空比寄存器
static volatile uint16_t mock_pwm_duty = 0;

// ==================== 控制参数结构体 ====================
typedef struct {
    float current_ref;          // 参考电流 (A)
    float current_sense;        // 采样电流 (A)
    float current_error;        // 电流误差
    float kp;                   // 比例系数
    float ki;                   // 积分系数
    float integral;             // 积分项
    float output_duty;          // 输出占空比 (0.0 ~ 1.0)
    uint16_t adc_offset;        // ADC 偏移校准值
    float sense_resistor;       // 采样电阻 (Ohm)
} FlybackCurrentControl_t;

// ==================== 电流采样校准函数 ====================
void CurrentSamplingCalibration(FlybackCurrentControl_t *ctrl) {
    // 模拟读取 ADC 原始值（带偏移校准）
    uint16_t adc_raw = mock_adc_current_raw;
    uint16_t adc_calibrated = (adc_raw > ctrl->adc_offset) ? 
                              (adc_raw - ctrl->adc_offset) : 0;

    // 转换为电压 (V)
    float voltage = (float)adc_calibrated * ADC_REF_VOLTAGE / ADC_RESOLUTION;

    // 通过采样电阻计算电流 (A)
    ctrl->current_sense = voltage / ctrl->sense_resistor;
}

// ==================== 平均电流模式 PI 控制器 ====================
void AverageCurrentModePI(FlybackCurrentControl_t *ctrl) {
    // 计算误差
    ctrl->current_error = ctrl->current_ref - ctrl->current_sense;

    // 比例项
    float p_term = ctrl->kp * ctrl->current_error;

    // 积分项（带抗饱和）
    ctrl->integral += ctrl->ki * ctrl->current_error;
    if (ctrl->integral > 1.0f) ctrl->integral = 1.0f;
    if (ctrl->integral < -1.0f) ctrl->integral = -1.0f;

    // 总输出
    float output = p_term + ctrl->integral;

    // 限幅到 [0, 1]
    if (output > 1.0f) output = 1.0f;
    if (output < 0.0f) output = 0.0f;

    ctrl->output_duty = output;

    // 更新 PWM 寄存器（Mock）
    mock_pwm_duty = (uint16_t)(output * PWM_DUTY_MAX);
}

// ==================== 初始化函数 ====================
void FlybackControl_Init(FlybackCurrentControl_t *ctrl) {
    ctrl->current_ref    = 1.0f;      // 目标电流 1A
    ctrl->kp             = 0.5f;
    ctrl->ki             = 0.1f;
    ctrl->integral       = 0.0f;
    ctrl->output_duty    = 0.0f;
    ctrl->adc_offset     = 10;        // 假设 ADC 偏移 10 LSB
    ctrl->sense_resistor = 0.1f;      // 100mΩ 采样电阻
}

// ==================== 主函数 ====================
int main(void) {
    FlybackCurrentControl_t flyback_ctrl;
    FlybackControl_Init(&flyback_ctrl);

    printf("=== 反激变换器平均电流模式控制（电流采样校准）===\n");
    printf("初始参数：参考电流=%.2fA, Kp=%.2f, Ki=%.2f\n\n",
           flyback_ctrl.current_ref, flyback_ctrl.kp, flyback_ctrl.ki);

    // 模拟 10 个控制周期
    for (int cycle = 0; cycle < 10; cycle++) {
        // 模拟 ADC 采样值（随机变化，模拟真实情况）
        mock_adc_current_raw = 500 + (rand() % 200);

        // 执行电流采样校准
        CurrentSamplingCalibration(&flyback_ctrl);

        // 执行 PI 控制
        AverageCurrentModePI(&flyback_ctrl);

        // 打印结果
        printf("周期 %2d | ADC原始=%4u | 校准电流=%.3fA | 误差=%.3fA | 占空比=%.3f\n",
               cycle + 1,
               mock_adc_current_raw,
               flyback_ctrl.current_sense,
               flyback_ctrl.current_error,
               flyback_ctrl.output_duty);
    }

    printf("\n控制结束。\n");
    return 0;
}
