// 模拟ADC寄存器
static uint16_t mock_adc1_dr = 0;
#define ADC1_DR         mock_adc1_dr

// 模拟GPIO
static uint32_t mock_gpioa_odr = 0;
#define GPIOA_ODR       mock_gpioa_odr

// ==================== 控制参数结构体 ====================
typedef struct {
    float duty_cycle;
    float phase_shift;
    float dead_time;
    float switching_freq;
    uint32_t timer_period;
    float input_voltage;
    float output_voltage;
    float output_current;
    float soft_switch_delay;
} PhaseShiftControl_t;

// ==================== 全局变量 ====================
static PhaseShiftControl_t g_ps_control = {
    .duty_cycle = 0.45f,
    .phase_shift = 0.1f,
    .dead_time = 0.000002f,
    .switching_freq = 100000.0f,
    .timer_period = 1000,
    .input_voltage = 400.0f,
    .output_voltage = 48.0f,
    .output_current = 10.0f,
    .soft_switch_delay = 0.0000005f
};

// ==================== 辅助函数 ====================
static void delay_us(float us) {
    volatile uint32_t count = (uint32_t)(us * 10.0f);
    while(count > 0) {
        count--;
    }
}

static uint16_t mock_adc_read(void) {
    static uint16_t adc_val = 2048;
    int16_t delta = (rand() % 100) - 50;
    if(delta > 0) {
        if(adc_val > 4095 - delta) {
            adc_val = 4095;
        } else {
            adc_val += (uint16_t)delta;
        }
    } else {
        if(adc_val < (uint16_t)(-delta)) {
            adc_val = 0;
        } else {
            adc_val -= (uint16_t)(-delta);
        }
    }
    return adc_val;
}

// ==================== 核心控制算法 ====================
static float calculate_phase_shift(float vin, float vout, float iout) {
    float k = 0.001f;
    float denom = iout + 0.1f;
    if(denom < 0.001f) denom = 0.001f;
    float phase = k * (vout / vin) * (1.0f / denom);

    if(phase > 0.5f) phase = 0.5f;
    if(phase < 0.01f) phase = 0.01f;

    return phase;
}

static float calculate_soft_switch_delay(float iout, float vin) {
    float delay = 0.000001f;
    float denom = iout + 1.0f;
    if(denom < 0.001f) denom = 0.001f;
    delay += 0.0000001f * (vin / denom);

    if(delay > 0.000003f) delay = 0.000003f;
    if(delay < 0.0000001f) delay = 0.0000001f;

    return delay;
}

static void update_pwm_phase_shift(float phase_shift_rad) {
    uint32_t period = g_ps_control.timer_period;
    if(period == 0) period = 1000;
    uint32_t half_period = period / 2;
    if(half_period == 0) half_period = 1;

    float pi_val = 3.14159265f;
    float denom = 2.0f * pi_val;
    if(denom < 0.001f) denom = 0.001f;
    uint32_t phase_count = (uint32_t)((phase_shift_rad / denom) * period);

    uint32_t q1_off = half_period;
    uint32_t q2_off = period;
    uint32_t q3_off = half_period + phase_count;
    uint32_t q4_off = period + phase_count;

    if(period > 0) {
        q3_off %= period;
        q4_off %= period;
    }

    TIM1_CCR1 = q1_off;
    TIM1_CCR2 = q2_off;
    TIM1_CCR3 = q3_off;
    TIM1_CCR4 = q4_off;

    TIM1_BDTR = (uint32_t)(g_ps_control.dead_time * 100000000.0f);
}

static void soft_switch_control(void) {
    static bool last_switch_state = false;
    bool current_switch_state = (TIM1_SR & 0x01) ? true : false;

    if(current_switch_state != last_switch_state) {
        float delay = g_ps_control.soft_switch_delay;

        GPIOA_ODR ^= 0x01;

        float delay_us_val = delay * 1000000.0f;
        if(delay_us_val > 0.0f) {
            delay_us(delay_us_val);
        }

        GPIOA_ODR &= ~0x01;

        last_switch_state = current_switch_state;
    }
}

static void phase_shift_control_loop(void) {
    uint16_t adc_vin = mock_adc_read();
    uint16_t adc_vout = mock_adc_read();
    uint16_t adc_iout = mock_adc_read();

    float vin = (float)adc_vin * 400.0f / 4096.0f;
    float vout = (float)adc_vout * 60.0f / 4096.0f;
    float iout = (float)adc_iout * 20.0f / 4096.0f;

    g_ps_control.input_voltage = vin;
    g_ps_control.output_voltage = vout;
    g_ps_control.output_current = iout;

    g_ps_control.phase_shift = calculate_phase_shift(vin, vout, iout);
    g_ps_control.soft_switch_delay = calculate_soft_switch_delay(iout, vin);

    update_pwm_phase_shift(g_ps_control.phase_shift);
    soft_switch_control();

    printf("Vin=%.1fV Vout=%.1fV Iout=%.1fA Phase=%.3frad Delay=%.2fus\n",
           vin, vout, iout, g_ps_control.phase_shift,
           g_ps_control.soft_switch_delay * 1000000.0f);
}

int main(void) {
    printf("=== 移相全桥ZVZCS控制 (辅助网络软开关) ===\n");
    printf("初始化控制参数...\n");

    TIM1_CR1 = 0x01;
    TIM1_ARR = 1000;
    TIM1_BDTR = 200;

    for(int i = 0; i < 10; i++) {
        printf("\n--- 控制周期 %d ---\n", i+1);
        phase_shift_control_loop();
        delay_us(100.0f);
    }

    printf("\n控制算法测试完成.\n");
    return 0;
}
