            PWM_CTRL_REG &= ~0x04;  // 清除高端使能位
            PWM_CTRL_REG |= 0x02;   // 设置低端使能位

            if (current_tick >= (hs_duty_ticks + dead_time_ticks + ls_duty_ticks)) {
                current_state = BUCK_STATE_DEAD_TIME;
                PWM_CTRL_REG &= ~0x02;  // 关断低端
            }
            break;

        case BUCK_STATE_DEAD_TIME:
            // 死区时间，检测体二极管导通
            diode_conduction = check_body_diode_conduction();
            adjust_dead_time(diode_conduction);

            if (current_tick >= (hs_duty_ticks + dead_time_ticks)) {
                current_state = BUCK_STATE_LS_ON;
            } else if (current_tick >= pwm_period_ticks) {
                current_state = BUCK_STATE_HS_ON;
                // 重置计数器
                TIMER_CNT = 0;
            }
            break;
    }
}

// 主函数
int main(void) {
    printf("同步整流Buck变换器体二极管导通抑制控制算法\n");
    printf("初始化控制参数...\n");

