    for (int cycle = 0; cycle < 5; cycle++) {
        printf("\n--- 周期 %d ---\n", cycle + 1);

        // 模拟PWM周期内的控制
        for (uint32_t tick = 0; tick < pwm_period_ticks; tick += 10) {
