// ==================== 数据结构 ====================
typedef struct {
    float voltage;          // 当前模块电压（V）
    float duty_cycle;       // 当前模块占空比（0.0 ~ 1.0）
    float voltage_error;    // 电压误差
    float integral;         // 积分项
} Module_t;

// ==================== 全局变量 ====================
Module_t modules[ADC_CHANNEL_NUM];
float avg_voltage = 0.0f;

// PID 参数（主动均压）
const float Kp = 0.5f;
const float Ki = 0.1f;
const float Kd = 0.0f;
const float integral_limit = 0.3f;  // 积分限幅

// ==================== Mock 函数 ====================
// 模拟读取 ADC 值（返回 0~4095）
uint16_t mock_adc_read(uint8_t channel) {
    // 模拟不同模块电压：模块0电压略高，模块1略低，其余正常
    float base = VOLTAGE_REF;
    switch(channel) {
        case 0: return (uint16_t)((base + 20) * 4095.0f / 1000.0f);  // 520V
        case 1: return (uint16_t)((base - 15) * 4095.0f / 1000.0f);  // 485V
        case 2: return (uint16_t)((base + 5)  * 4095.0f / 1000.0f);  // 505V
        case 3: return (uint16_t)((base - 10) * 4095.0f / 1000.0f);  // 490V
        default: return 0;
    }
}

// 模拟写入 PWM 占空比（使用数组模拟寄存器）
static uint32_t pwm_registers[ADC_CHANNEL_NUM] = {0};

void mock_pwm_write(uint8_t module_index, float duty) {
    // 限幅
    if (duty < 0.05f) duty = 0.05f;
    if (duty > 0.95f) duty = 0.95f;

    if (module_index < ADC_CHANNEL_NUM) {
        pwm_registers[module_index] = (uint32_t)(duty * PWM_PERIOD);
    }
}

// ==================== 核心控制算法 ====================
void voltage_balancing_control(void) {
    float sum_voltage = 0.0f;

    // 1. 读取所有模块电压
    for (int i = 0; i < ADC_CHANNEL_NUM; i++) {
        uint16_t adc_val = mock_adc_read(i);
        modules[i].voltage = (float)adc_val * 1000.0f / 4095.0f;  // 转换为电压
        sum_voltage += modules[i].voltage;
    }

    // 2. 计算平均电压
    if (ADC_CHANNEL_NUM > 0) {
        avg_voltage = sum_voltage / ADC_CHANNEL_NUM;
    } else {
        avg_voltage = 0.0f;
    }

    // 3. 对每个模块进行 PI 控制
    for (int i = 0; i < ADC_CHANNEL_NUM; i++) {
        // 误差 = 平均电压 - 模块电压（正误差表示模块电压偏低，需增加占空比）
        float error = avg_voltage - modules[i].voltage;
        modules[i].voltage_error = error;

        // 积分项
        modules[i].integral += error * Ki;

        // 积分限幅
        if (modules[i].integral > integral_limit) 
            modules[i].integral = integral_limit;
        if (modules[i].integral < -integral_limit) 
            modules[i].integral = -integral_limit;

        // 比例项
        float proportional = error * Kp;

        // 微分项（此处简化，未使用）
        float derivative = 0.0f;

        // 计算占空比调整量
        float delta_duty = proportional + modules[i].integral + derivative;

        // 更新占空比（基准占空比设为 0.5）
        modules[i].duty_cycle = 0.5f + delta_duty;

        // 限幅
        if (modules[i].duty_cycle < 0.05f) modules[i].duty_cycle = 0.05f;
        if (modules[i].duty_cycle > 0.95f) modules[i].duty_cycle = 0.95f;

        // 写入 PWM 寄存器
        mock_pwm_write(i, modules[i].duty_cycle);
    }
}

// ==================== 初始化 ====================
void system_init(void) {
    for (int i = 0; i < ADC_CHANNEL_NUM; i++) {
        modules[i].voltage = VOLTAGE_REF;
        modules[i].duty_cycle = 0.5f;
        modules[i].voltage_error = 0.0f;
        modules[i].integral = 0.0f;
    }
    printf("System initialized. Reference voltage: %d V\n", VOLTAGE_REF);
}

// ==================== 主函数 ====================
int main(void) {
    system_init();

    // 模拟运行 5 个控制周期
    for (int cycle = 0; cycle < 5; cycle++) {
        printf("\n========== Control Cycle %d ==========\n", cycle + 1);

        // 执行均压控制
        voltage_balancing_control();

        // 打印结果
        printf("Average voltage: %.2f V\n", avg_voltage);
        for (int i = 0; i < ADC_CHANNEL_NUM; i++) {
            printf("Module %d: Voltage=%.2f V, Duty=%.3f, Error=%.2f V\n",
                   i, modules[i].voltage, modules[i].duty_cycle, modules[i].voltage_error);
        }
    }

    printf("\nControl algorithm test completed.\n");
    return 0;
}
