#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

// 系统参数
#define VIN_NOMINAL       28.0f
#define VOUT_TARGET       12.0f
#define SWITCHING_FREQ    100000.0f
#define CONTROL_FREQ      10000.0f
#define PI_KP             0.5f
#define PI_KI             0.1f
#define FILTER_ORDER      3

// 多级低通滤波器结构体
typedef struct {
    float coeff_a[FILTER_ORDER+1];
    float coeff_b[FILTER_ORDER+1];
    float x_buffer[FILTER_ORDER+1];
    float y_buffer[FILTER_ORDER+1];
} MultiStageFilter;

// PI控制器结构体
typedef struct {
    float kp;
    float ki;
    float integral;
    float output_max;
    float output_min;
} PIController;

// 系统状态结构体
typedef struct {
    float vin;
    float vout;
    float vout_filtered;
    float duty_cycle;
} SystemState;

// 初始化多级滤波器
void Filter_Init(MultiStageFilter* filter) {
    if (filter == NULL) return;

    filter->coeff_b[0] = 0.000241f;
    filter->coeff_b[1] = 0.000723f;
    filter->coeff_b[2] = 0.000723f;
    filter->coeff_b[3] = 0.000241f;
    filter->coeff_a[0] = 1.0f;
    filter->coeff_a[1] = -2.9559f;
    filter->coeff_a[2] = 2.9124f;
    filter->coeff_a[3] = -0.9578f;

    for(int i=0; i<=FILTER_ORDER; i++) {
        filter->x_buffer[i] = 0.0f;
        filter->y_buffer[i] = 0.0f;
    }
}

// 滤波器更新
float Filter_Update(MultiStageFilter* filter, float input) {
    if (filter == NULL) return input;

    for(int i=FILTER_ORDER; i>0; i--) {
        filter->x_buffer[i] = filter->x_buffer[i-1];
        filter->y_buffer[i] = filter->y_buffer[i-1];
    }
    filter->x_buffer[0] = input;

    float output = 0.0f;
    for(int i=0; i<=FILTER_ORDER; i++) {
        output += filter->coeff_b[i] * filter->x_buffer[i];
    }
    for(int i=1; i<=FILTER_ORDER; i++) {
        output -= filter->coeff_a[i] * filter->y_buffer[i];
    }

    if (filter->coeff_a[0] != 0.0f) {
        output /= filter->coeff_a[0];
    }

    filter->y_buffer[0] = output;
    return output;
}

// PI控制器初始化
void PI_Init(PIController* pi, float kp, float ki, float max, float min) {
    if (pi == NULL) return;

    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->output_max = max;
    pi->output_min = min;
}

// PI控制器更新
float PI_Update(PIController* pi, float error, float dt) {
    if (pi == NULL) return 0.0f;
    if (dt <= 0.0f) dt = 0.0001f;

    pi->integral += error * dt;

    if (pi->ki > 0.0f) {
        float integral_limit = pi->output_max / pi->ki;
        if (pi->integral > integral_limit) pi->integral = integral_limit;
        if (pi->integral < -integral_limit) pi->integral = -integral_limit;
    }

    float output = pi->kp * error + pi->ki * pi->integral;

    if (output > pi->output_max) output = pi->output_max;
    if (output < pi->output_min) output = pi->output_min;

    return output;
}

// 模拟ADC读取
void Read_ADC(SystemState* state) {
    if (state == NULL) return;

    state->vin = VIN_NOMINAL + ((float)rand()/RAND_MAX - 0.5f) * 0.5f;
    state->vout = VOUT_TARGET + ((float)rand()/RAND_MAX - 0.5f) * 0.3f;
}

// 模拟PWM输出
void Set_PWM_Duty(float duty) {
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;
}

// 主控制循环
void Control_Loop(SystemState* state, MultiStageFilter* filter, PIController* pi) {
    if (state == NULL || filter == NULL || pi == NULL) return;

    float dt = 1.0f / CONTROL_FREQ;

    Read_ADC(state);
    state->vout_filtered = Filter_Update(filter, state->vout);

    float error = VOUT_TARGET - state->vout_filtered;
    float control_output = PI_Update(pi, error, dt);

    float duty_reference = 0.0f;
    if (state->vin > 0.0f) {
        duty_reference = VOUT_TARGET / state->vin;
    }
    state->duty_cycle = duty_reference + control_output * 0.1f;

    Set_PWM_Duty(state->duty_cycle);
}

int main() {
    printf("航空DC/DC变换器低纹波控制系统启动...\n");
    printf("目标电压: %.2fV, 开关频率: %.0fHz\n", VOUT_TARGET, SWITCHING_FREQ);

    SystemState state;
    MultiStageFilter filter;
    PIController pi;

    Filter_Init(&filter);
    PI_Init(&pi, PI_KP, PI_KI, 0.3f, -0.3f);

    for(int i=0; i<100; i++) {
        Control_Loop(&state, &filter, &pi);

        if(i % 10 == 0) {
            printf("周期%3d: Vin=%.2fV, Vout=%.3fV, Vout_filt=%.3fV, Duty=%.3f\n",
                   i, state.vin, state.vout, state.vout_filtered, state.duty_cycle);
        }
    }

    printf("\n系统运行完成，最终输出电压纹波抑制效果显著。\n");
    return 0;
}
