// 模拟硬件寄存器宏定义 - 使用静态变量替代指针访问
static uint32_t mock_tim_cr1 = 0;
static uint32_t mock_tim_sr = 0;
static uint32_t mock_gpio_odr = 0;

#define TIM_CR1_CEN             (1 << 0)
#define TIM_SR_UIF              (1 << 0)
#define GPIO_ODR_LED            (1 << 13)

// 隔离电压监测参数
#define ISOLATION_THRESHOLD_HIGH    3300
#define ISOLATION_THRESHOLD_LOW     2700
#define SAMPLE_COUNT                10

// 光耦反馈状态
typedef enum {
    ISO_STATUS_NORMAL = 0,
    ISO_STATUS_OVER_VOLTAGE,
    ISO_STATUS_UNDER_VOLTAGE,
    ISO_STATUS_FAULT
} IsolationStatus;

// 全局变量
static uint16_t adc_buffer[SAMPLE_COUNT];
static uint8_t sample_index = 0;
static uint32_t sample_sum = 0;
static bool buffer_full = false;

// 模拟ADC读取函数
static uint16_t mock_adc_read(void) {
    static uint16_t counter = 2000;
    counter += 100;
    if (counter > 4000) counter = 2000;
    return counter;
}

// 滑动平均滤波
static uint16_t moving_average_filter(uint16_t new_sample) {
    if (buffer_full) {
        sample_sum -= adc_buffer[sample_index];
    }
    adc_buffer[sample_index] = new_sample;
    sample_sum += new_sample;
    sample_index = (sample_index + 1) % SAMPLE_COUNT;

    if (sample_index == 0) {
        buffer_full = true;
    }

    uint8_t count = buffer_full ? SAMPLE_COUNT : sample_index;
    if (count == 0) count = 1;
    return (uint16_t)(sample_sum / count);
}

// 隔离电压监测算法
static IsolationStatus monitor_isolation_voltage(uint16_t filtered_adc) {
    uint32_t voltage_mv = (uint32_t)filtered_adc * 3300 / 4095;

    if (voltage_mv > ISOLATION_THRESHOLD_HIGH) {
        return ISO_STATUS_OVER_VOLTAGE;
    } else if (voltage_mv < ISOLATION_THRESHOLD_LOW) {
        return ISO_STATUS_UNDER_VOLTAGE;
    } else {
        return ISO_STATUS_NORMAL;
    }
}

// 光耦反馈控制
static void optocoupler_feedback_control(IsolationStatus status) {
    switch (status) {
        case ISO_STATUS_NORMAL:
            mock_gpio_odr &= ~GPIO_ODR_LED;
            break;
        case ISO_STATUS_OVER_VOLTAGE:
        case ISO_STATUS_UNDER_VOLTAGE:
            mock_gpio_odr |= GPIO_ODR_LED;
            break;
        case ISO_STATUS_FAULT:
            mock_gpio_odr ^= GPIO_ODR_LED;
            break;
    }
}

// 系统初始化
static void system_init(void) {
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        adc_buffer[i] = 0;
    }
    sample_sum = 0;
    sample_index = 0;
    buffer_full = false;

    mock_tim_cr1 |= TIM_CR1_CEN;
    mock_gpio_odr &= ~GPIO_ODR_LED;

    printf("医疗DC/DC变换器隔离电压监测系统初始化完成\n");
}

int main(void) {
    system_init();

    // 主循环 - 使用有限循环避免死循环
    for (int loop_count = 0; loop_count < 10; loop_count++) {
        // 模拟定时器更新标志
        mock_tim_sr |= TIM_SR_UIF;

        // 检查定时器更新标志
        if (mock_tim_sr & TIM_SR_UIF) {
            mock_tim_sr &= ~TIM_SR_UIF;

            // 读取ADC采样值
            uint16_t raw_adc = mock_adc_read();

            // 滑动平均滤波
            uint16_t filtered_adc = moving_average_filter(raw_adc);

            // 隔离电压监测
            IsolationStatus status = monitor_isolation_voltage(filtered_adc);

            // 光耦反馈控制
            optocoupler_feedback_control(status);

            // 调试打印
            uint32_t voltage_mv = (uint32_t)filtered_adc * 3300 / 4095;
            printf("ADC: %4u, 电压: %4umV, 状态: ", filtered_adc, voltage_mv);
            switch (status) {
                case ISO_STATUS_NORMAL:
                    printf("正常\n");
                    break;
                case ISO_STATUS_OVER_VOLTAGE:
                    printf("过压!\n");
                    break;
                case ISO_STATUS_UNDER_VOLTAGE:
                    printf("欠压!\n");
                    break;
                case ISO_STATUS_FAULT:
                    printf("故障!\n");
                    break;
            }
        }
    }

    printf("\n测试完成\n");
    return 0;
}
