#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

// 模拟寄存器定义
static uint32_t mock_current_sense_reg = 0;
static uint32_t mock_pwm_duty_reg = 1000;
static uint32_t mock_ocp_flag_reg = 0;

#define TIM_CURRENT_SENSE_REG  mock_current_sense_reg
#define TIM_PWM_DUTY_REG       mock_pwm_duty_reg
#define TIM_OCP_FLAG_REG       mock_ocp_flag_reg

// 反时限过流保护参数
#define I_NOMINAL              10.0f   // 额定电流 (A)
#define T_MAX                  5.0f    // 最大允许时间 (s)
#define K                      1.2f    // 反时限曲线系数
#define ALPHA                  2.0f    // 反时限曲线指数

// 保护状态机
typedef enum {
    OCP_STATE_NORMAL,
    OCP_STATE_ALARM,
    OCP_STATE_TRIP
} ocp_state_t;

// 反时限保护控制器结构体
typedef struct {
    float i_measured;           // 当前测量电流
    float i_pu;                 // 标幺值 (相对于额定电流)
    float t_trip;               // 计算出的跳闸时间
    float t_integral;           // 积分时间
    ocp_state_t state;          // 当前状态
    uint32_t tick_ms;           // 系统时间戳 (ms)
} ocp_controller_t;

// 全局控制器实例
static ocp_controller_t ocp_ctrl;

// 初始化反时限保护
void ocp_init(void) {
    ocp_ctrl.i_measured = 0.0f;
    ocp_ctrl.i_pu = 0.0f;
    ocp_ctrl.t_trip = 0.0f;
    ocp_ctrl.t_integral = 0.0f;
    ocp_ctrl.state = OCP_STATE_NORMAL;
    ocp_ctrl.tick_ms = 0;

    // 初始化模拟寄存器
    TIM_CURRENT_SENSE_REG = 0;
    TIM_PWM_DUTY_REG = 1000;  // 初始占空比 50%
    TIM_OCP_FLAG_REG = 0;
}

// 反时限特性计算: t_trip = K / (I_pu^ALPHA - 1)
float ocp_calculate_trip_time(float i_pu) {
    if (i_pu <= 1.0f) {
        return 1e10f;  // 正常电流，返回一个很大的值表示不会跳闸
    }

    float denominator = powf(i_pu, ALPHA) - 1.0f;
    if (denominator <= 0.0f) {
        return 1e10f;
    }

    float t = K / denominator;
    if (t > T_MAX) {
        return T_MAX;
    }
    return t;
}

// 更新保护状态 (每1ms调用一次)
void ocp_update(void) {
    // 读取模拟电流采样值 (假设ADC值直接对应电流)
    ocp_ctrl.i_measured = (float)(TIM_CURRENT_SENSE_REG) / 100.0f;
    ocp_ctrl.i_pu = ocp_ctrl.i_measured / I_NOMINAL;

    // 计算反时限跳闸时间
    ocp_ctrl.t_trip = ocp_calculate_trip_time(ocp_ctrl.i_pu);

    // 状态机处理
    switch (ocp_ctrl.state) {
        case OCP_STATE_NORMAL:
            if (ocp_ctrl.i_pu > 1.0f) {
                // 过流开始，进入告警状态
                ocp_ctrl.state = OCP_STATE_ALARM;
                ocp_ctrl.t_integral = 0.0f;
                printf("[OCP] Overcurrent detected: I=%.2fA (%.2f pu)\n", 
                       ocp_ctrl.i_measured, ocp_ctrl.i_pu);
            }
            break;

        case OCP_STATE_ALARM:
            if (ocp_ctrl.i_pu <= 1.0f) {
                // 电流恢复正常
                ocp_ctrl.state = OCP_STATE_NORMAL;
                ocp_ctrl.t_integral = 0.0f;
                printf("[OCP] Current returned to normal\n");
            } else {
                // 积分时间累加 (1ms步长)
                ocp_ctrl.t_integral += 0.001f;

                // 检查是否达到跳闸条件
                if (ocp_ctrl.t_integral >= ocp_ctrl.t_trip) {
                    ocp_ctrl.state = OCP_STATE_TRIP;
                    printf("[OCP] TRIP! I=%.2fA, t_integral=%.3fs > t_trip=%.3fs\n",
                           ocp_ctrl.i_measured, ocp_ctrl.t_integral, ocp_ctrl.t_trip);

                    // 执行保护动作：关闭PWM
                    TIM_PWM_DUTY_REG = 0;
                    TIM_OCP_FLAG_REG = 1;
                }
            }
            break;

        case OCP_STATE_TRIP:
            // 跳闸后需要手动复位或等待电流恢复正常
            if (ocp_ctrl.i_pu <= 0.5f) {  // 电流降到50%以下允许复位
                ocp_ctrl.state = OCP_STATE_NORMAL;
                ocp_ctrl.t_integral = 0.0f;
                TIM_PWM_DUTY_REG = 1000;  // 恢复PWM
                TIM_OCP_FLAG_REG = 0;
                printf("[OCP] Reset after fault cleared\n");
            }
            break;
    }

    ocp_ctrl.tick_ms++;
}

// 模拟电流采样 (用于测试)
void ocp_simulate_current(float current) {
    TIM_CURRENT_SENSE_REG = (uint32_t)(current * 100.0f);
}

// 主函数
int main(void) {
    printf("Industrial DC/DC Converter OCP (Inverse Time) Demo\n");
    printf("==================================================\n");
