#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// 模拟ADC读取电压（单位：V）
#define ADC_READ_VOLTAGE()  (12.0f)  // 假设稳态电压12V

// 模拟PWM占空比设置（0.0 ~ 1.0）
#define PWM_SET_DUTY(duty)  // 空实现

// 阶跃响应参数
#define STEP_AMPLITUDE      0.05f   // 占空比阶跃幅度（5%）
#define SETTLING_TIME_MS    100     // 最大等待稳定时间（ms）
#define SAMPLE_INTERVAL_MS  1       // 采样间隔（ms）

// PID参数结构体
typedef struct {
    float kp;
    float ki;
    float kd;
} PIDParams;

// 系统参数结构体
typedef struct {
    float steady_state_voltage;  // 稳态电压
    float overshoot;             // 超调量（%）
    float rise_time_ms;          // 上升时间（ms）
    float settling_time_ms;      // 调节时间（ms）
} SystemResponse;

// 模拟延时函数（毫秒级）
void delay_ms(int ms) {
    volatile int i, j;
    for (i = 0; i < ms; i++)
        for (j = 0; j < 10000; j++);
}

// 获取当前电压（模拟ADC）
float get_voltage(void) {
    return ADC_READ_VOLTAGE();
}

// 施加阶跃扰动并记录响应
SystemResponse perform_step_response(float initial_duty, float step_duty) {
    SystemResponse resp = {0};
    float voltage_samples[SETTLING_TIME_MS];
    float max_voltage = 0, min_voltage = 1e6;
    float final_voltage = 0;
    int i, rise_start = 0, rise_end = 0;
    int settling_start = 0;

    // 记录初始稳态
    float initial_voltage = get_voltage();
    printf("Initial voltage: %.3f V\n", initial_voltage);

    // 施加阶跃
    PWM_SET_DUTY(initial_duty + step_duty);
    delay_ms(1);  // 等待一个采样周期

    // 采样响应曲线
    for (i = 0; i < SETTLING_TIME_MS; i++) {
        voltage_samples[i] = get_voltage();
        if (voltage_samples[i] > max_voltage) max_voltage = voltage_samples[i];
        if (voltage_samples[i] < min_voltage) min_voltage = voltage_samples[i];
        delay_ms(SAMPLE_INTERVAL_MS);
    }

    // 计算最终稳态（取最后10个点的平均值）
    for (i = SETTLING_TIME_MS - 10; i < SETTLING_TIME_MS; i++) {
        final_voltage += voltage_samples[i];
    }
    final_voltage /= 10.0f;

    // 计算超调量
    float voltage_step = final_voltage - initial_voltage;
    if (voltage_step > 0) {
        resp.overshoot = (max_voltage - final_voltage) / voltage_step * 100.0f;
    } else {
        resp.overshoot = (final_voltage - min_voltage) / (-voltage_step) * 100.0f;
    }

    // 计算上升时间（10% ~ 90%）
    float target_10 = initial_voltage + 0.1f * voltage_step;
    float target_90 = initial_voltage + 0.9f * voltage_step;
    for (i = 0; i < SETTLING_TIME_MS; i++) {
        if (voltage_samples[i] >= target_10 && rise_start == 0) {
            rise_start = i;
        }
        if (voltage_samples[i] >= target_90 && rise_end == 0) {
            rise_end = i;
            break;
        }
    }
    resp.rise_time_ms = (rise_end - rise_start) * SAMPLE_INTERVAL_MS;

    // 计算调节时间（进入±2%误差带）
    float tolerance = 0.02f * fabs(voltage_step);
    for (i = SETTLING_TIME_MS - 1; i >= 0; i--) {
        if (fabs(voltage_samples[i] - final_voltage) > tolerance) {
            settling_start = i + 1;
            break;
        }
    }
    resp.settling_time_ms = (SETTLING_TIME_MS - settling_start) * SAMPLE_INTERVAL_MS;

    resp.steady_state_voltage = final_voltage;
    return resp;
}

// 根据阶跃响应计算PID参数（Ziegler-Nichols法）
PIDParams calculate_pid_params(SystemResponse resp, float step_amplitude) {
    PIDParams pid = {0};
    float K = resp.steady_state_voltage / step_amplitude;  // 系统增益
    float T = resp.rise_time_ms;                           // 时间常数（近似）
    float L = resp.settling_time_ms * 0.1f;                // 延迟时间（近似）

    // Ziegler-Nichols PID整定公式
    pid.kp = 1.2f * T / (K * L);
    pid.ki = 0.6f * T / (K * L * L);
    pid.kd = 0.6f * T / K;

    return pid;
}

int main(void) {
    printf("DC/DC Converter Parameter Auto-Tuning (Step Response Method)\n");
    printf("============================================================\n\n");

    // 初始占空比50%
    float initial_duty = 0.5f;
    PWM_SET_DUTY(initial_duty);
    delay_ms(50);  // 等待系统稳定

    // 执行阶跃响应测试
    printf("Performing step response test...\n");
    SystemResponse resp = perform_step_response(initial_duty, STEP_AMPLITUDE);

    // 打印响应特性
    printf("\nSystem Response Characteristics:\n");
    printf("  Steady-state voltage: %.3f V\n", resp.steady_state_voltage);
    printf("  Overshoot: %.2f %%\n", resp.overshoot);
    printf("  Rise time: %.2f ms\n", resp.rise_time_ms);
    printf("  Settling time: %.2f ms\n", resp.settling_time_ms);

    // 计算PID参数
    PIDParams pid = calculate_pid_params(resp, STEP_AMPLITUDE);
    printf("\nCalculated PID Parameters (Ziegler-Nichols):\n");
    printf("  Kp: %.4f\n", pid.kp);
    printf("  Ki: %.4f\n", pid.ki);
    printf("  Kd: %.4f\n", pid.kd);

    // 恢复初始占空比
    PWM_SET_DUTY(initial_duty);
    printf("\nTuning complete. System returned to initial state.\n");

    return 0;
}
