#define PWM_DUTY_REG              mock_pwm_duty
#define MODE_CONTROL_REG          mock_mode
#define ENABLE_REG                mock_enable

// ==================== 控制参数 ====================
#define PI 3.14159265f
#define GRID_FREQUENCY 50.0f          // 电网频率 50Hz
#define SAMPLE_FREQUENCY 20000.0f     // 采样频率 20kHz
#define DT (1.0f / SAMPLE_FREQUENCY)  // 采样周期

// PI控制器参数 (能量回馈模式)
#define KP_VOLTAGE 0.5f    // 电压环比例系数
#define KI_VOLTAGE 10.0f   // 电压环积分系数
#define KP_CURRENT 0.2f    // 电流环比例系数
#define KI_CURRENT 5.0f    // 电流环积分系数

// 系统参数
#define DC_BUS_REF 400.0f  // 直流母线参考电压 (V)
#define GRID_PEAK 311.0f   // 电网电压峰值 (V)
#define MAX_CURRENT 10.0f  // 最大允许电流 (A)

// ==================== 全局变量 ====================
static float grid_theta = 0.0f;          // 电网相位角
static float voltage_error_integral = 0.0f;
static float current_error_integral = 0.0f;
static float current_ref = 0.0f;         // 电流参考值
static float prev_current = 0.0f;        // 上一周期电流值

// ==================== 锁相环 (PLL) 模拟 ====================
void pll_update(float grid_voltage) {
    // 模拟相位累加
    grid_theta += 2.0f * PI * GRID_FREQUENCY * DT;
    if (grid_theta > 2.0f * PI) {
        grid_theta -= 2.0f * PI;
    }
}

// ==================== PI控制器 ====================
float pi_controller(float error, float *integral, float kp, float ki, float limit) {
    *integral += error * DT;
    // 抗积分饱和
    if (*integral > limit / ki) *integral = limit / ki;
    if (*integral < -limit / ki) *integral = -limit / ki;

    float output = kp * error + ki * (*integral);
    // 输出限幅
    if (output > limit) output = limit;
    if (output < -limit) output = -limit;
    return output;
}

// ==================== 能量回馈控制主函数 ====================
void energy_feedback_control(void) {
    // 读取采样值
    float grid_voltage = GRID_VOLTAGE_SAMPLE_REG;
    float dc_bus_voltage = DC_BUS_VOLTAGE_SAMPLE_REG;
    float inductor_current = INDUCTOR_CURRENT_SAMPLE_REG;

    // 更新PLL相位
    pll_update(grid_voltage);

    // 电压外环：控制直流母线电压
    float voltage_error = DC_BUS_REF - dc_bus_voltage;
    float current_amplitude = pi_controller(voltage_error, &voltage_error_integral,
                                            KP_VOLTAGE, KI_VOLTAGE, MAX_CURRENT);

    // 生成与电网同步的正弦电流参考 (回馈时电流与电网电压反相)
    float sin_theta = sinf(grid_theta);
    current_ref = current_amplitude * sin_theta;  // 负号表示能量回馈

    // 电流内环：跟踪电流参考
    float current_error = current_ref - inductor_current;
    float duty_cycle = pi_controller(current_error, &current_error_integral,
                                     KP_CURRENT, KI_CURRENT, 0.95f);

    // 占空比偏移到0.5附近 (双向DC/DC通常需要偏置)
    duty_cycle = 0.5f + duty_cycle * 0.5f;
    if (duty_cycle > 0.95f) duty_cycle = 0.95f;
    if (duty_cycle < 0.05f) duty_cycle = 0.05f;

    // 写入PWM寄存器
    PWM_DUTY_REG = duty_cycle;
}

// ==================== 主函数 ====================
int main(void) {
    // 初始化模拟寄存器
    GRID_VOLTAGE_SAMPLE_REG = 0.0f;
    DC_BUS_VOLTAGE_SAMPLE_REG = 400.0f;
    INDUCTOR_CURRENT_SAMPLE_REG = 0.0f;
    PWM_DUTY_REG = 0.5f;
    MODE_CONTROL_REG = 1;  // 回馈模式
    ENABLE_REG = 1;        // 使能

    printf("双向DC/DC变换器能量回馈控制系统启动\n");
    printf("直流母线参考电压: %.1f V\n", DC_BUS_REF);
    printf("电网频率: %.1f Hz\n", GRID_FREQUENCY);
    printf("采样频率: %.0f Hz\n\n", SAMPLE_FREQUENCY);

    // 模拟运行10个电网周期
    int total_samples = (int)(10.0f * SAMPLE_FREQUENCY / GRID_FREQUENCY);
    for (int i = 0; i < total_samples; i++) {
        // 模拟电网电压变化 (正弦波)
        float time = i * DT;
        float grid_voltage = GRID_PEAK * sinf(2.0f * PI * GRID_FREQUENCY * time);
        GRID_VOLTAGE_SAMPLE_REG = grid_voltage;

        // 模拟直流母线电压轻微波动
        DC_BUS_VOLTAGE_SAMPLE_REG = 400.0f + 5.0f * sinf(2.0f * PI * 100.0f * time);

        // 执行控制算法
        if (ENABLE_REG && MODE_CONTROL_REG == 1) {
            energy_feedback_control();
        }

        // 每100个采样点打印一次状态
        if (i % 100 == 0) {
            printf("采样点 %4d | 电网电压: %7.2f V | 母线电压: %7.2f V | "
                   "电感电流: %7.3f A | 占空比: %5.3f | 电流参考: %7.3f A\n",
                   i, GRID_VOLTAGE_SAMPLE_REG, DC_BUS_VOLTAGE_SAMPLE_REG,
                   INDUCTOR_CURRENT_SAMPLE_REG, PWM_DUTY_REG, current_ref);
        }

        // 模拟电感电流响应 (简单一阶滞后)
        float target_current = current_ref;
        INDUCTOR_CURRENT_SAMPLE_REG = prev_current + 0.1f * (target_current - prev_current);
        prev_current = INDUCTOR_CURRENT_SAMPLE_REG;
    }

    printf("\n控制算法运行完成\n");
    return 0;
}
