    PWM_TIMER_ARR = PWM_PERIOD;
    ADC_CR2 = 0;

    // 运行控制循环
    for (int cycle = 0; cycle < 3; cycle++)
    {
        printf("\n--- Control Cycle %d ---\n", cycle + 1);
        dc_dc_control_loop();
    }

    printf("\n=== Test Complete ===\n");
    return 0;
}
