    // 限幅
    if (sys->pv_voltage < 0) sys->pv_voltage = 0;
    if (sys->pv_current < 0) sys->pv_current = 0;
}

// 读取ADC采样值 (mock)
void ReadADCSamples(MPPT_System_t *sys) {
    sys->pv_voltage = ADC_READ_VOLTAGE();
    sys->pv_current = ADC_READ_CURRENT();
    sys->pv_power = sys->pv_voltage * sys->pv_current;
}

// 扰动观察法(P&O) MPPT算法
void MPPT_PerturbAndObserve(MPPT_System_t *sys) {
    float delta_power = sys->pv_power - sys->prev_power;
    float delta_duty = sys->duty_cycle - sys->prev_duty;

    // 判断功率变化方向
    if (fabs(delta_power) < MPPT_POWER_THRESHOLD) {
        // 功率变化很小，保持当前方向
        sys->duty_cycle += sys->mppt_direction * MPPT_STEP_SIZE;
    } else {
        if (delta_power > 0) {
            // 功率增加，继续同方向扰动
            sys->duty_cycle += sys->mppt_direction * MPPT_STEP_SIZE;
        } else {
            // 功率减少，反向扰动
            sys->mppt_direction = -sys->mppt_direction;
            sys->duty_cycle += sys->mppt_direction * MPPT_STEP_SIZE;
        }
    }

    // 限幅占空比
    if (sys->duty_cycle < DCDC_DUTY_MIN) sys->duty_cycle = DCDC_DUTY_MIN;
    if (sys->duty_cycle > DCDC_DUTY_MAX) sys->duty_cycle = DCDC_DUTY_MAX;

    // 更新历史值
    sys->prev_power = sys->pv_power;
    sys->prev_duty = sys->duty_cycle;

    // 输出PWM
    PWM_SET_DUTY(sys->duty_cycle);
}

// 执行MPPT控制周期
void MPPT_ControlCycle(MPPT_System_t *sys) {
    // 1. 读取当前采样值
    ReadADCSamples(sys);

    // 2. 执行MPPT算法
    MPPT_PerturbAndObserve(sys);

    // 3. 打印状态
    printf("[MPPT] V=%.2fV, I=%.2fA, P=%.2fW, Duty=%.3f\n",
           sys->pv_voltage, sys->pv_current, sys->pv_power, sys->duty_cycle);
}

int main() {
    printf("=== Photovoltaic DC/DC Converter MPPT Control Simulation ===\n\n");

    // 初始化随机数种子
