    printf("\nRunning %d MPPT control cycles...\n\n", num_cycles);

    for (int i = 0; i < num_cycles; i++) {
        printf("Cycle %2d: ", i + 1);
        MPPT_ControlCycle(&mppt_sys);

        // 模拟采样间隔
