    REG_FAULT_STATUS |= fault_type;
    printf("[FAULT] 注入故障: 0x%X\n", fault_type);
}

// 清除故障标志
static void clear_fault(uint32_t fault_type) {
    REG_FAULT_CLEAR = fault_type;
    REG_FAULT_STATUS &= ~fault_type;
    printf("[CLEAR] 清除故障: 0x%X\n", fault_type);
}

// 重启PWM输出
static void restart_pwm(void) {
    REG_PWM_ENABLE = 0;
    delay_ms(10); // 10ms 关闭时间
    REG_PWM_ENABLE = 1;
    printf("[PWM] PWM输出已重启\n");
}

// 系统软复位
static void system_soft_reset(void) {
    printf("[RESET] 执行系统软复位\n");
    REG_SYSTEM_RESET = 1;
    // 模拟复位后的初始化
    hardware_init();
}

// 故障自恢复主逻辑
static bool fault_recovery(uint32_t fault_type) {
    static uint8_t retry_count = 0;
    static uint32_t last_fault = 0;

    printf("[RECOVERY] 检测到故障: 0x%X\n", fault_type);

    // 检查是否是新故障
    if (fault_type != last_fault) {
        last_fault = fault_type;
        retry_count = 0;
    }

    if (retry_count >= MAX_RETRY_COUNT) {
        printf("[RECOVERY] 重试次数已达上限，执行系统复位\n");
        system_soft_reset();
        return false;
    }

    // 执行恢复步骤
    printf("[RECOVERY] 第%d次恢复尝试\n", retry_count + 1);

    // 步骤1: 关闭PWM输出
    REG_PWM_ENABLE = 0;
    printf("[STEP1] PWM输出已关闭\n");

    // 步骤2: 清除故障标志
    clear_fault(fault_type);

    // 步骤3: 等待恢复时间
    delay_ms(RETRY_DELAY_MS);
    printf("[STEP2] 等待%dms完成\n", RETRY_DELAY_MS);

    // 步骤4: 重启PWM
    restart_pwm();

    // 步骤5: 检查故障是否清除
    if ((REG_FAULT_STATUS & fault_type) == 0) {
        printf("[RECOVERY] 恢复成功\n");
        retry_count++;
        return true;
    } else {
        printf("[RECOVERY] 恢复失败，故障仍然存在\n");
        retry_count++;
        return false;
    }
}

