#define TEMP_NOMINAL (25.0f)

// 补偿参数结构体
typedef struct {
    float temp_coeff_a;  // 温度系数A
    float temp_coeff_b;  // 温度系数B
    float temp_coeff_c;  // 温度系数C
    float base_duty;     // 25℃时的基准占空比
    float base_voltage;  // 基准输出电压
} CompensationParams;

// DC/DC变换器状态结构体
typedef struct {
    float current_temp;      // 当前温度(℃)
    float target_voltage;    // 目标输出电压(V)
    float current_duty;      // 当前PWM占空比(0.0-1.0)
    float current_voltage;   // 当前输出电压(V)
    CompensationParams params;
} DCDCConverter;

// 初始化补偿参数
void InitCompensationParams(CompensationParams* params) {
    params->temp_coeff_a = 0.0005f;   // 二次项系数
    params->temp_coeff_b = 0.02f;     // 一次项系数
    params->temp_coeff_c = 1.0f;      // 常数项
    params->base_duty = 0.5f;         // 50%占空比
    params->base_voltage = 12.0f;     // 12V输出
}

// 初始化变换器
void InitConverter(DCDCConverter* converter) {
    converter->current_temp = TEMP_NOMINAL;
    converter->target_voltage = 12.0f;
    converter->current_duty = 0.5f;
    converter->current_voltage = 12.0f;
    InitCompensationParams(&converter->params);
}

// 读取温度传感器(模拟)
float ReadTemperature(void) {
    // 模拟读取温度寄存器
    return 25.0f;  // 默认返回25℃
}

// 读取输出电压(模拟)
float ReadOutputVoltage(void) {
    // 模拟读取电压寄存器
    return 12.0f;  // 默认返回12V
}

// 设置PWM占空比(模拟)
void SetPWMDuty(float duty) {
    // 限制占空比范围
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;
    // 写入PWM寄存器(模拟)
    printf("[PWM] 设置占空比: %.3f\n", duty);
}

// 温度补偿计算
float TemperatureCompensation(const CompensationParams* params, float temp) {
    float delta_temp = temp - TEMP_NOMINAL;
    // 使用二次多项式补偿
    float compensation = params->temp_coeff_a * delta_temp * delta_temp +
                         params->temp_coeff_b * delta_temp +
                         params->temp_coeff_c;
    return compensation;
}

// 计算补偿后的目标占空比
float CalculateCompensatedDuty(const DCDCConverter* converter) {
    float compensation = TemperatureCompensation(&converter->params, converter->current_temp);
    float voltage_ratio = converter->target_voltage / converter->params.base_voltage;
    float compensated_duty = converter->params.base_duty * voltage_ratio * compensation;

    // 限制占空比范围
    if (compensated_duty < 0.1f) compensated_duty = 0.1f;
    if (compensated_duty > 0.9f) compensated_duty = 0.9f;

    return compensated_duty;
}

// 主控制循环
void ControlLoop(DCDCConverter* converter) {
    // 读取当前温度
    converter->current_temp = ReadTemperature();

    // 读取当前输出电压
    converter->current_voltage = ReadOutputVoltage();

    // 计算补偿后的占空比
    float new_duty = CalculateCompensatedDuty(converter);

    // 应用新的占空比
    SetPWMDuty(new_duty);
    converter->current_duty = new_duty;
}

