    // 测试不同温度下的补偿效果
    float test_temps[] = {-40.0f, -20.0f, 0.0f, 25.0f, 50.0f, 70.0f, 85.0f};
    int num_tests = sizeof(test_temps) / sizeof(test_temps[0]);

    printf("温度(℃)\t补偿系数\t补偿后占空比\n");
    printf("----------------------------------------\n");

    for (int i = 0; i < num_tests; i++) {
        converter->current_temp = test_temps[i];
        float compensation = TemperatureCompensation(&converter->params, test_temps[i]);
        float duty = CalculateCompensatedDuty(converter);
        printf("%.1f\t\t%.4f\t\t%.4f\n", test_temps[i], compensation, duty);
    }

    printf("\n========== 测试完成 ==========\n");
}

int main() {
    DCDCConverter converter;
    InitConverter(&converter);

    // 运行测试
