// 光伏电池模型 (单二极管模型简化)
typedef struct {
    float voc;      // 开路电压
    float isc;      // 短路电流
    float vmp;      // 最大功率点电压
    float imp;      // 最大功率点电流
    float ns;       // 串联数
    float np;       // 并联数
} PVPanel;

// DC/DC变换器模型 (Boost变换器)
typedef struct {
    float duty;     // 占空比 (0-1)
    float vin;      // 输入电压
    float iin;      // 输入电流
    float vout;     // 输出电压
    float iout;     // 输出电流
    float l;        // 电感值
    float c;        // 电容值
    float rl;       // 电感电阻
    float freq;     // 开关频率
} DCDCConverter;

// MPPT控制器 (扰动观察法)
typedef struct {
    float vpv_old;      // 上一周期光伏电压
    float ppv_old;      // 上一周期光伏功率
    float duty;         // 当前占空比
    float step;         // 扰动步长
    float period;       // 控制周期
    float threshold;    // 功率变化阈值
    int direction;      // 扰动方向 (1:增加, -1:减少)
} MPPTController;

// 初始化光伏面板
void pv_init(PVPanel *pv) {
    pv->voc = PV_VOC;
    pv->isc = PV_ISC;
    pv->vmp = PV_VMP;
    pv->imp = PV_IMP;
    pv->ns = NS;
    pv->np = NP;
}

// 计算光伏输出功率 (简化模型)
float pv_calc_power(PVPanel *pv, float vpv) {
    if (vpv < 0 || vpv > pv->voc) return 0.0f;

    // 简化I-V特性: 线性近似
    float ipv = pv->isc * (1.0f - vpv / pv->voc);
    return vpv * ipv;
}

// 初始化DC/DC变换器
void dcdc_init(DCDCConverter *dcdc) {
    dcdc->duty = 0.5f;
    dcdc->vin = 0.0f;
    dcdc->iin = 0.0f;
    dcdc->vout = 0.0f;
    dcdc->iout = 0.0f;
    dcdc->l = DCDC_L;
    dcdc->c = DCDC_C;
    dcdc->rl = DCDC_RL;
    dcdc->freq = DCDC_FREQ;
}

// 更新DC/DC变换器状态 (稳态近似)
void dcdc_update(DCDCConverter *dcdc, float duty, float vin) {
    dcdc->duty = duty;
    dcdc->vin = vin;

    // Boost变换器稳态关系 (忽略损耗)
    if (duty < 0.99f && duty > 0.01f) {
        dcdc->vout = vin / (1.0f - duty);
        dcdc->iin = dcdc->vout * dcdc->iout / vin;
    } else {
        dcdc->vout = vin;
        dcdc->iin = dcdc->iout;
    }
}

// 初始化MPPT控制器
void mppt_init(MPPTController *mppt) {
    mppt->vpv_old = 0.0f;
    mppt->ppv_old = 0.0f;
    mppt->duty = 0.5f;
    mppt->step = MPPT_STEP;
    mppt->period = MPPT_PERIOD;
    mppt->threshold = MPPT_THRESH;
    mppt->direction = 1;
}

// MPPT扰动观察法算法
float mppt_perturb_observe(MPPTController *mppt, float vpv, float ipv) {
    float ppv = vpv * ipv;
    float delta_p = ppv - mppt->ppv_old;
    float delta_v = vpv - mppt->vpv_old;

    // 判断功率变化方向
    if (fabs(delta_p) > mppt->threshold) {
        if (delta_p > 0) {
            // 功率增加，保持扰动方向
            if (delta_v > 0) {
                mppt->direction = 1;  // 增加占空比
            } else {
                mppt->direction = -1; // 减小占空比
            }
        } else {
            // 功率减小，反转扰动方向
            if (delta_v > 0) {
                mppt->direction = -1;
            } else {
                mppt->direction = 1;
            }
        }
    }

    // 更新占空比
    mppt->duty += mppt->direction * mppt->step;

    // 限幅
    if (mppt->duty > 0.95f) mppt->duty = 0.95f;
    if (mppt->duty < 0.05f) mppt->duty = 0.05f;

    // 保存当前值
    mppt->vpv_old = vpv;
    mppt->ppv_old = ppv;

    return mppt->duty;
}

// 主控制循环
void mppt_control_loop(PVPanel *pv, DCDCConverter *dcdc, MPPTController *mppt) {
    // 模拟读取ADC值
    float vpv = mock_reg_read(REG_ADC_VPV);
    float ipv = mock_reg_read(REG_ADC_IPV);

    // 应用MPPT算法
    float new_duty = mppt_perturb_observe(mppt, vpv, ipv);

    // 更新DC/DC变换器
    dcdc_update(dcdc, new_duty, vpv);

    // 模拟写入PWM寄存器
    mock_reg_write(REG_PWM_DUTY, new_duty);

    // 打印状态
