static uint32_t mock_pwm_register = 500;
static uint32_t mock_adc_register = 2048;
static uint32_t mock_timer_register = 0;

// 宏定义模拟寄存器读写 - 使用静态变量避免指针解引用
#define REG_WRITE(addr, val) \
    do { \
        if ((addr) == 0x4000) mock_pwm_register = (val); \
        else if ((addr) == 0x4004) mock_adc_register = (val); \
        else if ((addr) == 0x4008) mock_timer_register = (val); \
    } while(0)

#define REG_READ(addr) \
    ((addr) == 0x4000 ? mock_pwm_register : \
     (addr) == 0x4004 ? mock_adc_register : \
     (addr) == 0x4008 ? mock_timer_register : 0)

// 系统参数定义
#define SOC_REF_PERCENT     50.0f
#define SOC_HYSTERESIS      2.0f
#define PWM_PERIOD          1000
#define CONTROL_PERIOD_MS   10
#define BATTERY_CAPACITY_AH 100.0f

// 控制参数
typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float output_limit;
} PIDController;

// DC/DC变换器状态
typedef struct {
    float soc_percent;
    float battery_current;
    float battery_voltage;
    float duty_cycle;
    bool charging_mode;
} DCDCConverter;

// 初始化PID控制器
void PID_Init(PIDController *pid, float kp, float ki, float kd, float limit) {
    if (pid == NULL) return;
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_limit = limit;
}

// PID计算函数
float PID_Compute(PIDController *pid, float setpoint, float measurement, float dt) {
    if (pid == NULL || dt <= 0.0001f) return 0.0f;

    float error = setpoint - measurement;

    // 比例项
    float p_term = pid->kp * error;

    // 积分项(带抗饱和)
    pid->integral += error * dt;
    if (pid->ki > 0.0001f) {
        float integral_max = pid->output_limit / pid->ki;
        if (pid->integral > integral_max) {
            pid->integral = integral_max;
        } else if (pid->integral < -integral_max) {
            pid->integral = -integral_max;
        }
    }
    float i_term = pid->ki * pid->integral;

    // 微分项
    float d_term = pid->kd * (error - pid->prev_error) / dt;

    // 保存误差
    pid->prev_error = error;

    // 总输出
    float output = p_term + i_term + d_term;

    // 输出限幅
    if (output > pid->output_limit) output = pid->output_limit;
    if (output < -pid->output_limit) output = -pid->output_limit;

    return output;
}

// 模拟ADC读取SOC
float Read_SOC(void) {
    uint32_t adc_value = REG_READ(0x4004);
    return (float)adc_value * 100.0f / 4095.0f;
}

// 模拟读取电池电流
float Read_Battery_Current(void) {
    return 5.0f;
}

// 模拟读取电池电压
float Read_Battery_Voltage(void) {
    return 48.0f;
}

// 设置PWM占空比
void Set_PWM_Duty(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;

    uint32_t pwm_value = (uint32_t)(duty_cycle * PWM_PERIOD);
    REG_WRITE(0x4000, pwm_value);
}

// SOC闭环控制主函数
void SOC_Control_Loop(DCDCConverter *conv, PIDController *pid) {
    if (conv == NULL || pid == NULL) return;

    float dt = CONTROL_PERIOD_MS / 1000.0f;

    // 读取当前状态
    conv->soc_percent = Read_SOC();
    conv->battery_current = Read_Battery_Current();
    conv->battery_voltage = Read_Battery_Voltage();

    // 计算SOC误差(带滞环控制)
    float error = SOC_REF_PERCENT - conv->soc_percent;
    float hysteresis_band = SOC_HYSTERESIS;

    // 滞环逻辑
    if (error > hysteresis_band) {
        conv->charging_mode = true;
    } else if (error < -hysteresis_band) {
        conv->charging_mode = false;
    }

    // PID计算占空比调整量
    float pid_output = PID_Compute(pid, SOC_REF_PERCENT, conv->soc_percent, dt);

    // 根据充放电模式调整占空比
    if (conv->charging_mode) {
        conv->duty_cycle = 0.5f + pid_output;
    } else {
        conv->duty_cycle = 0.5f - pid_output;
    }

    // 限制占空比范围
    if (conv->duty_cycle < 0.1f) conv->duty_cycle = 0.1f;
    if (conv->duty_cycle > 0.9f) conv->duty_cycle = 0.9f;

    // 应用占空比到硬件
    Set_PWM_Duty(conv->duty_cycle);
}

// 模拟系统初始化
void System_Init(DCDCConverter *conv) {
    if (conv == NULL) return;

    conv->soc_percent = 50.0f;
    conv->battery_current = 0.0f;
    conv->battery_voltage = 48.0f;
    conv->duty_cycle = 0.5f;
    conv->charging_mode = true;

    REG_WRITE(0x4004, 2048);
    REG_WRITE(0x4000, 500);
}

// 模拟系统运行
void Simulate_System_Run(DCDCConverter *conv, PIDController *pid, int steps) {
    if (conv == NULL || pid == NULL || steps <= 0) return;

    printf("=== SOC闭环控制仿真开始 ===\n");
    printf("目标SOC: %.1f%%\n", SOC_REF_PERCENT);
    printf("控制周期: %dms\n\n", CONTROL_PERIOD_MS);

    for (int i = 0; i < steps; i++) {
        SOC_Control_Loop(conv, pid);

        printf("Step %d: SOC=%.2f%%, 电流=%.2fA, 电压=%.2fV, 占空比=%.3f, 模式=%s\n",
               i+1,
               conv->soc_percent,
               conv->battery_current,
               conv->battery_voltage,
               conv->duty_cycle,
               conv->charging_mode ? "充电" : "放电");

        // 模拟SOC变化
        float delta_soc = (conv->battery_current * CONTROL_PERIOD_MS / 3600000.0f) 
                         / BATTERY_CAPACITY_AH * 100.0f;
        if (conv->charging_mode) {
            conv->soc_percent += delta_soc;
        } else {
            conv->soc_percent -= delta_soc;
        }

        uint32_t adc_val = (uint32_t)(conv->soc_percent * 4095.0f / 100.0f);
        REG_WRITE(0x4004, adc_val);
    }

    printf("\n=== 仿真结束 ===\n");
}

int main(void) {
    DCDCConverter converter;
    PIDController pid;

    System_Init(&converter);
    PID_Init(&pid, 0.3f, 0.1f, 0.05f, 0.3f);

    Simulate_System_Run(&converter, &pid, 20);

    printf("\n测试打印: PID控制器参数 Kp=%.2f, Ki=%.2f, Kd=%.2f\n", 
           pid.kp, pid.ki, pid.kd);
    printf("最终SOC: %.2f%%, 占空比: %.3f\n", 
           converter.soc_percent, converter.duty_cycle);

    return 0;
}
