#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* 模拟硬件寄存器定义 - 使用简单变量替代指针访问 */
static uint32_t mock_pwm_a = 0;
static uint32_t mock_pwm_b = 0;
static uint32_t mock_pwm_c = 0;
static uint32_t mock_adc_voltage = 0;
static uint32_t mock_adc_current = 0;

/* 宏定义：读写模拟寄存器 */
#define REG_READ(addr) (addr)
#define REG_WRITE(addr, val) (addr = (val))

/* 系统参数 */
#define GRID_FREQ 50.0f
#define SAMPLE_FREQ 10000.0f
#define PI 3.14159265358979323846f
#define VIRTUAL_CAP 0.001f  /* 虚拟电容值 1mF */
#define L_FILTER 0.005f     /* 滤波电感 5mH */

/* 控制结构体 */
typedef struct {
    float vd_ref;      /* d轴电压参考 */
    float vq_ref;      /* q轴电压参考 */
    float id_ref;      /* d轴电流参考 */
    float iq_ref;      /* q轴电流参考 */
    float vd_fb;       /* d轴电压反馈 */
    float vq_fb;       /* q轴电压反馈 */
    float id_fb;       /* d轴电流反馈 */
    float iq_fb;       /* q轴电流反馈 */
    float vd_error;    /* d轴电压误差 */
    float vq_error;    /* q轴电压误差 */
    float id_error;    /* d轴电流误差 */
    float iq_error;    /* q轴电流误差 */
    float vd_integral; /* d轴电压积分 */
    float vq_integral; /* q轴电压积分 */
    float id_integral; /* d轴电流积分 */
    float iq_integral; /* q轴电流积分 */
    float vd_out;      /* d轴电压环输出 */
    float vq_out;      /* q轴电压环输出 */
    float id_out;      /* d轴电流环输出 */
    float iq_out;      /* q轴电流环输出 */
    float theta;       /* 电网角度 */
    float vdc;         /* 直流母线电压 */
} InverterControl_t;

/* 全局控制变量 */
static InverterControl_t g_ctrl = {0};

/* 虚拟电容法解耦计算 */
static void virtual_capacitor_decoupling(float id_ref, float iq_ref,
                                         float vd_fb, float vq_fb,
                                         float *vd_comp, float *vq_comp)
{
    /* 虚拟电容产生的补偿电压：Vc = (1/C) * ∫i dt → 频域近似为 i/(jωC) */
    float omega = 2.0f * PI * GRID_FREQ;
    float cap_impedance = 1.0f / (omega * VIRTUAL_CAP);

    /* 解耦补偿：d轴补偿来自q轴电流，q轴补偿来自d轴电流（负号） */
    *vd_comp = -omega * L_FILTER * iq_ref + cap_impedance * iq_ref;
    *vq_comp =  omega * L_FILTER * id_ref - cap_impedance * id_ref;
}

/* PI控制器 */
static float pi_controller(float error, float *integral, 
                           float kp, float ki, float ts)
{
    *integral += error * ts;
    return kp * error + ki * (*integral);
}

/* 坐标变换：abc到dq */
static void abc_to_dq(float a, float b, float c, float theta,
                      float *d, float *q)
{
    float sin_t = sinf(theta);
    float cos_t = cosf(theta);
    *d = (2.0f/3.0f) * (a*cos_t + b*cos_t + c*cos_t);
    *q = (2.0f/3.0f) * (-a*sin_t - b*sin_t - c*sin_t);
}

/* 坐标变换：dq到abc */
static void dq_to_abc(float d, float q, float theta,
                      float *a, float *b, float *c)
{
    float sin_t = sinf(theta);
    float cos_t = cosf(theta);
    *a = d*cos_t - q*sin_t;
    *b = d*cos_t - q*sin_t;
    *c = d*cos_t - q*sin_t;
}

/* 主控制函数 */
static void inverter_control_loop(void)
{
    float ts = 1.0f / SAMPLE_FREQ;
    float va, vb, vc, ia, ib, ic;
    float vd_comp, vq_comp;
    float vd_ref_final, vq_ref_final;

    /* 读取模拟ADC值（模拟电网电压和电流） */
    uint32_t adc_val = REG_READ(mock_adc_voltage);
    va = (float)(adc_val & 0xFF) * 0.1f;
    vb = (float)((adc_val >> 8) & 0xFF) * 0.1f;
    vc = (float)((adc_val >> 16) & 0xFF) * 0.1f;

    adc_val = REG_READ(mock_adc_current);
    ia = (float)(adc_val & 0xFF) * 0.01f;
    ib = (float)((adc_val >> 8) & 0xFF) * 0.01f;
    ic = (float)((adc_val >> 16) & 0xFF) * 0.01f;

    /* 电网角度模拟（实际使用PLL） */
    g_ctrl.theta += 2.0f * PI * GRID_FREQ * ts;
    if (g_ctrl.theta > 2.0f * PI) g_ctrl.theta -= 2.0f * PI;

    /* abc到dq变换 */
    abc_to_dq(va, vb, vc, g_ctrl.theta, &g_ctrl.vd_fb, &g_ctrl.vq_fb);
    abc_to_dq(ia, ib, ic, g_ctrl.theta, &g_ctrl.id_fb, &g_ctrl.iq_fb);

    /* 电压外环PI控制（生成电流参考） */
    g_ctrl.vd_error = g_ctrl.vd_ref - g_ctrl.vd_fb;
    g_ctrl.vq_error = g_ctrl.vq_ref - g_ctrl.vq_fb;
    g_ctrl.id_ref = pi_controller(g_ctrl.vd_error, &g_ctrl.vd_integral, 0.5f, 10.0f, ts);
    g_ctrl.iq_ref = pi_controller(g_ctrl.vq_error, &g_ctrl.vq_integral, 0.5f, 10.0f, ts);

    /* 虚拟电容法解耦 */
    virtual_capacitor_decoupling(g_ctrl.id_ref, g_ctrl.iq_ref,
                                 g_ctrl.vd_fb, g_ctrl.vq_fb,
                                 &vd_comp, &vq_comp);

    /* 电流内环PI控制 */
    g_ctrl.id_error = g_ctrl.id_ref - g_ctrl.id_fb;
    g_ctrl.iq_error = g_ctrl.iq_ref - g_ctrl.iq_fb;
    g_ctrl.id_out = pi_controller(g_ctrl.id_error, &g_ctrl.id_integral, 2.0f, 50.0f, ts);
    g_ctrl.iq_out = pi_controller(g_ctrl.iq_error, &g_ctrl.iq_integral, 2.0f, 50.0f, ts);

    /* 加入解耦补偿 */
    vd_ref_final = g_ctrl.id_out + vd_comp;
    vq_ref_final = g_ctrl.iq_out + vq_comp;

    /* dq到abc变换生成PWM占空比 */
    dq_to_abc(vd_ref_final, vq_ref_final, g_ctrl.theta, &va, &vb, &vc);

    /* 写入PWM寄存器（模拟） */
    REG_WRITE(mock_pwm_a, (uint32_t)(va * 1000.0f));
    REG_WRITE(mock_pwm_b, (uint32_t)(vb * 1000.0f));
    REG_WRITE(mock_pwm_c, (uint32_t)(vc * 1000.0f));
}

/* 主函数 */
int main(void)
{
    int i;

    printf("光伏并网逆变器功率解耦控制（虚拟电容法）初始化...\n");

    /* 初始化控制参数 */
    g_ctrl.vd_ref = 311.0f;  /* 311V 相电压峰值 */
    g_ctrl.vq_ref = 0.0f;
    g_ctrl.vd_integral = 0.0f;
    g_ctrl.vq_integral = 0.0f;
    g_ctrl.id_integral = 0.0f;
    g_ctrl.iq_integral = 0.0f;
    g_ctrl.theta = 0.0f;

    printf("虚拟电容值: %.4f F\n", VIRTUAL_CAP);
    printf("滤波电感值: %.4f H\n", L_FILTER);
    printf("电网频率: %.1f Hz\n", GRID_FREQ);
    printf("采样频率: %.0f Hz\n\n", SAMPLE_FREQ);

    /* 运行10个控制周期测试 */
    for (i = 0; i < 10; i++) {
        inverter_control_loop();

        printf("周期 %d: vd_fb=%.2f, vq_fb=%.2f, id_ref=%.3f, iq_ref=%.3f\n",
               i+1, g_ctrl.vd_fb, g_ctrl.vq_fb, g_ctrl.id_ref, g_ctrl.iq_ref);
    }

    printf("\n控制算法测试完成。\n");
    return 0;
}
