// 模拟ADC读取电压的宏定义
#define READ_ADC_VIN()  (12.5f)  // 假设输入电压为12.5V

// UVLO阈值定义
#define UVLO_THRESHOLD_ON  10.0f   // 开启阈值：10V
#define UVLO_THRESHOLD_OFF 8.0f    // 关闭阈值：8V（带迟滞）

// 模拟PWM使能寄存器
static bool pwm_enable = false;

// 模拟ADC采样值
static float vin_voltage = 0.0f;

// 状态机定义
typedef enum {
    UVLO_STATE_UNDERVOLTAGE,  // 欠压状态
    UVLO_STATE_NORMAL         // 正常状态
} uvlo_state_t;

static uvlo_state_t uvlo_state = UVLO_STATE_UNDERVOLTAGE;

// UVLO控制函数
void uvlo_control(void) {
    // 读取当前输入电压
    vin_voltage = READ_ADC_VIN();

    // 状态机处理
    switch(uvlo_state) {
        case UVLO_STATE_UNDERVOLTAGE:
            // 如果电压上升到开启阈值以上，切换到正常状态
            if(vin_voltage >= UVLO_THRESHOLD_ON) {
                uvlo_state = UVLO_STATE_NORMAL;
                pwm_enable = true;
                printf("UVLO: Voltage %.2fV >= %.2fV, PWM enabled\n", 
                       vin_voltage, UVLO_THRESHOLD_ON);
            } else {
                pwm_enable = false;
                printf("UVLO: Voltage %.2fV < %.2fV, PWM disabled\n", 
                       vin_voltage, UVLO_THRESHOLD_ON);
            }
            break;

        case UVLO_STATE_NORMAL:
            // 如果电压下降到关闭阈值以下，切换到欠压状态
            if(vin_voltage <= UVLO_THRESHOLD_OFF) {
                uvlo_state = UVLO_STATE_UNDERVOLTAGE;
                pwm_enable = false;
                printf("UVLO: Voltage %.2fV <= %.2fV, PWM disabled\n", 
                       vin_voltage, UVLO_THRESHOLD_OFF);
            } else {
                pwm_enable = true;
                printf("UVLO: Voltage %.2fV > %.2fV, PWM enabled\n", 
                       vin_voltage, UVLO_THRESHOLD_OFF);
            }
            break;
    }
}

// 模拟主循环中的ADC采样更新
void update_vin_voltage(float new_voltage) {
    vin_voltage = new_voltage;
}

int main(void) {
    printf("DC/DC Converter UVLO Test\n");
    printf("Threshold ON: %.2fV, Threshold OFF: %.2fV\n\n", 
           UVLO_THRESHOLD_ON, UVLO_THRESHOLD_OFF);

    // 测试序列：模拟电压变化
    float test_voltages[] = {5.0f, 7.0f, 9.0f, 10.5f, 12.0f, 9.0f, 7.5f, 11.0f};
    int test_count = sizeof(test_voltages) / sizeof(test_voltages[0]);

    for(int i = 0; i < test_count; i++) {
        printf("Test %d: Setting VIN = %.2fV\n", i+1, test_voltages[i]);
        update_vin_voltage(test_voltages[i]);
        uvlo_control();
        printf("PWM Enable: %s\n\n", pwm_enable ? "YES" : "NO");
    }

    printf("UVLO test completed.\n");
    return 0;
}
