// 模拟硬件寄存器宏定义
#define TIMER_COUNTER_REG  (*((volatile uint32_t*)0x40000000))
#define TIMER_COMPARE_REG  (*((volatile uint32_t*)0x40000004))
#define PWM_DUTY_REG       (*((volatile uint32_t*)0x40000008))
#define ADC_VOLTAGE_REG    (*((volatile uint32_t*)0x4000000C))
#define ADC_CURRENT_REG    (*((volatile uint32_t*)0x40000010))
#define GPIO_MODE_REG      (*((volatile uint32_t*)0x40000014))
#define RELAY_CONTROL_REG  (*((volatile uint32_t*)0x40000018))
#define PLL_PHASE_REG      (*((volatile uint32_t*)0x4000001C))

// 系统参数
#define GRID_VOLTAGE_NOMINAL  230.0f
#define GRID_FREQUENCY_NOMINAL 50.0f
#define DC_BUS_VOLTAGE        400.0f
#define PWM_FREQUENCY         20000.0f
#define CONTROL_PERIOD_US     50.0f  // 20kHz控制周期

// 状态枚举
typedef enum {
    MODE_OFFLINE = 0,
    MODE_GRID_CONNECTED,
    MODE_ISLAND,
    MODE_TRANSITION_TO_GRID,
    MODE_TRANSITION_TO_ISLAND
} InverterMode;

// 控制结构体
typedef struct {
    float v_grid_measured;      // 电网电压测量值
    float f_grid_measured;      // 电网频率测量值
    float v_inv_output;         // 逆变器输出电压
    float i_inv_output;         // 逆变器输出电流
    float v_ref;                // 电压参考值
    float phase_angle;          // 锁相环角度
    float duty_cycle;           // PWM占空比 (0.0-1.0)
    bool grid_sync_ok;          // 电网同步标志
    InverterMode current_mode;  // 当前工作模式
    uint32_t transition_timer;  // 切换计时器
} InverterControl;

// 锁相环结构体
typedef struct {
    float theta;                // 输出角度
    float omega;                // 角频率
    float alpha;                // 滤波器系数
    float v_q;                  // q轴电压
} PLL_Controller;

// 全局控制变量
static InverterControl g_inv_ctrl;
static PLL_Controller g_pll;

// 初始化控制参数
void Inverter_Init(void) {
    g_inv_ctrl.v_ref = GRID_VOLTAGE_NOMINAL;
    g_inv_ctrl.current_mode = MODE_OFFLINE;
    g_inv_ctrl.grid_sync_ok = false;
    g_inv_ctrl.transition_timer = 0;
    g_inv_ctrl.duty_cycle = 0.0f;
    g_inv_ctrl.v_grid_measured = 0.0f;
    g_inv_ctrl.f_grid_measured = 0.0f;
    g_inv_ctrl.v_inv_output = 0.0f;
    g_inv_ctrl.i_inv_output = 0.0f;
    g_inv_ctrl.phase_angle = 0.0f;

    g_pll.theta = 0.0f;
    g_pll.omega = 2.0f * M_PI * GRID_FREQUENCY_NOMINAL;
    g_pll.alpha = 0.01f;
    g_pll.v_q = 0.0f;
}

// 模拟ADC读取
void Read_ADC_Values(void) {
    // 模拟电网电压和频率测量
    static float grid_phase = 0.0f;
    grid_phase += 2.0f * M_PI * GRID_FREQUENCY_NOMINAL * CONTROL_PERIOD_US * 1e-6f;
    if (grid_phase > 2.0f * M_PI) grid_phase -= 2.0f * M_PI;

    g_inv_ctrl.v_grid_measured = GRID_VOLTAGE_NOMINAL * sinf(grid_phase) + 5.0f;
    g_inv_ctrl.f_grid_measured = GRID_FREQUENCY_NOMINAL + 0.1f * sinf(grid_phase * 0.1f);

    // 模拟逆变器输出
    g_inv_ctrl.v_inv_output = g_inv_ctrl.v_ref * sinf(g_pll.theta);
    g_inv_ctrl.i_inv_output = 10.0f * sinf(g_pll.theta - 0.1f);
}

// 锁相环实现
void PLL_Update(float v_grid) {
    // 简化的同步参考坐标系PLL
    float v_alpha = v_grid;
    float v_beta = 0.0f;

    // Park变换 - 计算q轴分量用于锁相
    float v_q = -v_alpha * sinf(g_pll.theta) + v_beta * cosf(g_pll.theta);

    g_pll.v_q = v_q;

    // PI控制器简化
    float error = -v_q;
    g_pll.omega += g_pll.alpha * error;

    // 限制频率范围
    if (g_pll.omega < 2.0f * M_PI * 47.0f) g_pll.omega = 2.0f * M_PI * 47.0f;
    if (g_pll.omega > 2.0f * M_PI * 53.0f) g_pll.omega = 2.0f * M_PI * 53.0f;

    // 更新角度
    g_pll.theta += g_pll.omega * CONTROL_PERIOD_US * 1e-6f;
    if (g_pll.theta > 2.0f * M_PI) g_pll.theta -= 2.0f * M_PI;
}

// 电网同步检测
bool Check_Grid_Sync(void) {
    float v_diff = fabsf(g_inv_ctrl.v_inv_output - g_inv_ctrl.v_grid_measured);
    float phase_diff = fabsf(g_pll.theta - asinf(g_inv_ctrl.v_grid_measured / GRID_VOLTAGE_NOMINAL));

    return (v_diff < 0.05f * GRID_VOLTAGE_NOMINAL) && (phase_diff < 5.0f * M_PI / 180.0f);
}

// 离网模式控制
void Island_Control(void) {
    g_inv_ctrl.v_ref = GRID_VOLTAGE_NOMINAL;
    g_pll.omega = 2.0f * M_PI * GRID_FREQUENCY_NOMINAL;

    float v_error = g_inv_ctrl.v_ref - g_inv_ctrl.v_inv_output;
    static float integral = 0.0f;
    integral += v_error * CONTROL_PERIOD_US * 1e-6f;
    float duty = 0.5f + 0.1f * v_error + 0.05f * integral;

    if (duty > 0.95f) duty = 0.95f;
    if (duty < 0.05f) duty = 0.05f;

    g_inv_ctrl.duty_cycle = duty;
}

// 并网模式控制
void Grid_Connected_Control(void) {
    float i_ref = 20.0f * sinf(g_pll.theta);

    float i_error = i_ref - g_inv_ctrl.i_inv_output;
    static float integral_i = 0.0f;
    integral_i += i_error * CONTROL_PERIOD_US * 1e-6f;
    float duty = 0.5f + 0.2f * i_error + 0.1f * integral_i;

    if (duty > 0.95f) duty = 0.95f;
    if (duty < 0.05f) duty = 0.05f;

    g_inv_ctrl.duty_cycle = duty;
}

// 无缝切换控制主函数
void Seamless_Transition_Control(void) {
    Read_ADC_Values();
    PLL_Update(g_inv_ctrl.v_grid_measured);

    bool grid_present = (fabsf(g_inv_ctrl.v_grid_measured) > 0.8f * GRID_VOLTAGE_NOMINAL);
    g_inv_ctrl.grid_sync_ok = Check_Grid_Sync();

    switch (g_inv_ctrl.current_mode) {
        case MODE_OFFLINE:
            if (grid_present) {
                g_inv_ctrl.current_mode = MODE_TRANSITION_TO_GRID;
                g_inv_ctrl.transition_timer = 0;
                printf("Transition: Offline -> Grid Sync Start\n");
            } else {
                Island_Control();
            }
            break;

        case MODE_TRANSITION_TO_GRID:
            g_inv_ctrl.transition_timer++;
            Island_Control();

            if (g_inv_ctrl.grid_sync_ok && (g_inv_ctrl.transition_timer > 100)) {
                g_inv_ctrl.current_mode = MODE_GRID_CONNECTED;
                printf("Transition Complete: Grid Connected\n");
            }

            if (!grid_present) {
                g_inv_ctrl.current_mode = MODE_OFFLINE;
                printf("Transition Abort: Grid Lost\n");
            }
            break;

        case MODE_GRID_CONNECTED:
            if (!grid_present) {
                g_inv_ctrl.current_mode = MODE_TRANSITION_TO_ISLAND;
                g_inv_ctrl.transition_timer = 0;
                printf("Transition: Grid -> Island Start\n");
            } else {
                Grid_Connected_Control();
            }
            break;

        case MODE_TRANSITION_TO_ISLAND:
            g_inv_ctrl.transition_timer++;
            Island_Control();

            if (g_inv_ctrl.transition_timer > 10) {
                g_inv_ctrl.current_mode = MODE_ISLAND;
                printf("Transition Complete: Island Mode\n");
            }
            break;

        case MODE_ISLAND:
            if (grid_present && g_inv_ctrl.grid_sync_ok) {
                g_inv_ctrl.current_mode = MODE_TRANSITION_TO_GRID;
                g_inv_ctrl.transition_timer = 0;
                printf("Transition: Island -> Grid Sync Start\n");
            } else {
                Island_Control();
            }
            break;
    }
}

// 主函数
int main(void) {
    printf("Seamless Transition Control for Energy Storage Inverter\n");
    printf("======================================================\n\n");

    Inverter_Init();

    // 模拟运行1000个控制周期
    for (int cycle = 0; cycle < 1000; cycle++) {
        Seamless_Transition_Control();

        // 每50个周期打印一次状态
        if (cycle % 50 == 0) {
            printf("Cycle %4d | Mode: %d | Vgrid: %.2f | Vref: %.2f | Duty: %.3f | Sync: %d\n",
                   cycle,
