// 系统参数
#define SAMPLE_FREQ 10000.0f
#define DT (1.0f/SAMPLE_FREQ)
#define PI 3.141592653589793f

// 阻尼控制器参数
typedef struct {
    float kp;
    float ki;
    float kd;
    float tau;
    float integral;
    float prev_error;
    float prev_output;
    float filter_state;
} DampingController;

// 逆变器状态
typedef struct {
    float v_dc;
    float v_out;
    float i_out;
    float freq_ref;
    float freq_actual;
    float duty_cycle;
} InverterState;

// 初始化阻尼控制器
void DampingController_Init(DampingController* ctrl, float kp, float ki, float kd, float tau) {
    ctrl->kp = kp;
    ctrl->ki = ki;
    ctrl->kd = kd;
    ctrl->tau = tau;
    ctrl->integral = 0.0f;
    ctrl->prev_error = 0.0f;
    ctrl->prev_output = 0.0f;
    ctrl->filter_state = 0.0f;
}

// 低通滤波器
float LowPassFilter(float input, float* state, float alpha) {
    *state = alpha * input + (1.0f - alpha) * (*state);
    return *state;
}

// 阻尼控制算法
float DampingController_Update(DampingController* ctrl, float error) {
    float alpha = DT / (ctrl->tau + DT);
    float filtered_error = LowPassFilter(error, &ctrl->filter_state, alpha);

    float p_term = ctrl->kp * filtered_error;

    float i_term = ctrl->ki * filtered_error * DT;
    ctrl->integral += i_term;
    if (ctrl->integral > 1.0f) ctrl->integral = 1.0f;
    if (ctrl->integral < -1.0f) ctrl->integral = -1.0f;

    float derivative = (filtered_error - ctrl->prev_error) / DT;
    float d_term = ctrl->kd * derivative;

    float output = p_term + ctrl->integral + d_term;

    if (output > 1.0f) output = 1.0f;
    if (output < -1.0f) output = -1.0f;

    ctrl->prev_error = filtered_error;
    ctrl->prev_output = output;

    return output;
}

// 频率检测（模拟）
float DetectFrequency(float voltage) {
    static float prev_voltage = 0.0f;
    static float zero_cross_count = 0;

    if (prev_voltage <= 0.0f && voltage > 0.0f) {
        zero_cross_count++;
        if (zero_cross_count >= 2) {
            float period = DT * zero_cross_count;
            if (period > 0.0f) {
                float freq = 1.0f / period;
                zero_cross_count = 0;
                return freq;
            }
        }
    }
    prev_voltage = voltage;
    return 50.0f;
}

// 主控制循环
void InverterControlLoop(InverterState* inv, DampingController* ctrl) {
    // 模拟ADC读取
    float v_dc = 400.0f;
    float i_out = 10.0f;

    inv->v_dc = v_dc;
    inv->i_out = i_out;
    inv->v_out = v_dc * inv->duty_cycle;

    inv->freq_actual = DetectFrequency(inv->v_out);

    float freq_error = inv->freq_ref - inv->freq_actual;

    float damping_correction = DampingController_Update(ctrl, freq_error);

    inv->duty_cycle += damping_correction * 0.01f;

    if (inv->duty_cycle > 0.95f) inv->duty_cycle = 0.95f;
    if (inv->duty_cycle < 0.05f) inv->duty_cycle = 0.05f;
}

int main() {
    printf("Inverter Low-Frequency Oscillation Damping Control System\n");
    printf("========================================================\n\n");

    InverterState inverter;
    inverter.v_dc = 400.0f;
    inverter.v_out = 0.0f;
    inverter.i_out = 0.0f;
    inverter.freq_ref = 50.0f;
    inverter.freq_actual = 50.0f;
    inverter.duty_cycle = 0.5f;

    DampingController damping_ctrl;
    DampingController_Init(&damping_ctrl, 0.5f, 10.0f, 0.01f, 0.001f);

    printf("Initial State:\n");
    printf("  DC Voltage: %.1f V\n", inverter.v_dc);
    printf("  Reference Frequency: %.1f Hz\n", inverter.freq_ref);
    printf("  Initial Duty Cycle: %.3f\n\n", inverter.duty_cycle);

    printf("Running control loop simulation...\n\n");
    for (int i = 0; i < 1000; i++) {
        float disturbance = 2.0f * sinf(2.0f * PI * 5.0f * i * DT);
        inverter.freq_actual = 50.0f + disturbance;

        InverterControlLoop(&inverter, &damping_ctrl);

        if (i % 100 == 0) {
            printf("Step %4d: Freq_actual=%.2f Hz, Duty=%.4f, Correction=%.4f\n",
                   i, inverter.freq_actual, inverter.duty_cycle,
                   inverter.duty_cycle - 0.5f);
        }
    }

    printf("\nControl loop completed.\n");
    printf("Final duty cycle: %.4f\n", inverter.duty_cycle);

    printf("\nDamping Controller Step Response Test:\n");
    DampingController test_ctrl;
    DampingController_Init(&test_ctrl, 0.5f, 10.0f, 0.01f, 0.001f);

    float test_error = 1.0f;
    printf("Input error: %.2f Hz\n", test_error);
    for (int i = 0; i < 10; i++) {
        float output = DampingController_Update(&test_ctrl, test_error);
        printf("  Step %d: Output = %.6f\n", i+1, output);
    }

    return 0;
}
