void set_pwm_duty(float duty_cycle) {
    // 限制占空比在0-1之间
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;

    unsigned int reg_value = (unsigned int)(duty_cycle * PWM_PERIOD);
    // 模拟写入寄存器
    printf("[PWM] Duty: %.3f, Register: 0x%04X\n", duty_cycle, reg_value);
