// PFC控制算法主函数
void pfc_control(void) {
    // 1. 读取采样值
    v_dc = read_adc_voltage();
    i_ac = read_adc_current();
    v_ac = read_adc_ac_voltage();

    // 2. 电压外环PI控制
    float v_error = V_REF - v_dc;
    v_error_int += v_error * (1.0f / SAMPLE_FREQ);

    // 抗积分饱和
    if (v_error_int > 100.0f) v_error_int = 100.0f;
    if (v_error_int < -100.0f) v_error_int = -100.0f;

    float i_ref_amplitude = K_P * v_error + K_I * v_error_int;

    // 3. 生成电流参考（与电网电压同相）
    float i_ref = i_ref_amplitude * sinf(phase_angle);

    // 4. 电流内环比例控制
    float current_error = i_ref - i_ac;
    float duty_cycle = 0.5f + K_CURRENT * current_error;

    // 5. 输出PWM
    set_pwm_duty(duty_cycle);

    // 6. 更新相位角（锁相环简化模拟）
