// 模拟寄存器读写宏 - 使用uintptr_t避免指针转换警告
#define READ_REG(addr)    (*(volatile uint32_t *)(uintptr_t)(addr))
#define WRITE_REG(addr, val) (*(volatile uint32_t *)(uintptr_t)(addr) = (val))

// ==================== 系统参数 ====================
#define NUM_MODULES      4       // 模块数量
#define VOLTAGE_REF      48.0f   // 参考电压 (V)
#define CURRENT_SHARE_REF 10.0f  // 均流参考电流 (A)
#define PI_KP            0.5f    // PI比例系数
#define PI_KI            0.1f    // PI积分系数
#define PWM_MAX          1000    // 最大PWM占空比
#define PWM_MIN          0       // 最小PWM占空比
#define CONTROL_PERIOD   0.001f  // 控制周期 (s)

// ==================== 数据结构 ====================
typedef struct {
    float voltage;      // 模块输出电压 (V)
    float current;      // 模块输出电流 (A)
    float duty_cycle;   // 当前占空比 (0-1000)
    float integral;     // PI积分项
    float voltage_ref;  // 电压参考值
    float current_ref;  // 电流参考值
} Module_t;

// ==================== 全局变量 ====================
static Module_t modules[NUM_MODULES];
static float master_voltage_ref = VOLTAGE_REF;
static float total_current = 0.0f;
static float average_current = 0.0f;

// ==================== 模拟硬件读取函数 ====================
static float read_adc_voltage(uint8_t module_id) {
    // 模拟ADC读取，实际硬件中从寄存器读取
    // 使用模拟数据避免访问非法内存地址
    return 48.0f + (float)(module_id * 0.5f); // 模拟不同模块的电压
}

static float read_adc_current(uint8_t module_id) {
    // 使用模拟数据避免访问非法内存地址
    return 10.0f + (float)(module_id * 0.2f); // 模拟不同模块的电流
}

static void write_pwm_duty(uint8_t module_id, uint16_t duty) {
    // 模拟PWM写入，不实际访问硬件
    // 实际硬件中会写入寄存器
    (void)module_id;
    (void)duty;
}

// ==================== PI控制器 ====================
static float pi_controller(float error, float *integral, float kp, float ki, float dt) {
    *integral += error * dt;
    // 抗积分饱和
    if (*integral > 100.0f) *integral = 100.0f;
    if (*integral < -100.0f) *integral = -100.0f;
    return kp * error + ki * (*integral);
}

// ==================== 主从均压均流控制 ====================
static void master_voltage_control(void) {
    // 主模块电压环：调节总电压参考
    static float voltage_integral = 0.0f;
    float voltage_error = VOLTAGE_REF - modules[0].voltage;
    float voltage_output = pi_controller(voltage_error, &voltage_integral, PI_KP, PI_KI, CONTROL_PERIOD);

    // 更新所有模块的电压参考（主从同步）
    for (int i = 0; i < NUM_MODULES; i++) {
        modules[i].voltage_ref = VOLTAGE_REF + voltage_output;
    }
}

static void slave_current_share_control(void) {
    // 计算总电流和平均电流
    total_current = 0.0f;
    for (int i = 0; i < NUM_MODULES; i++) {
        total_current += modules[i].current;
    }
    average_current = total_current / NUM_MODULES;

    // 每个从模块的电流环
    for (int i = 0; i < NUM_MODULES; i++) {
        float current_error = average_current - modules[i].current;
        float current_output = pi_controller(current_error, &modules[i].integral, PI_KP, PI_KI, CONTROL_PERIOD);

        // 计算最终占空比（电压环输出 + 电流环校正）
        float duty = modules[i].voltage_ref * 20.0f + current_output; // 简化映射
        if (duty > PWM_MAX) duty = PWM_MAX;
        if (duty < PWM_MIN) duty = PWM_MIN;
        modules[i].duty_cycle = duty;
        write_pwm_duty(i, (uint16_t)duty);
    }
}

// ==================== 系统初始化 ====================
static void system_init(void) {
    printf("System Initializing...\n");
    for (int i = 0; i < NUM_MODULES; i++) {
        modules[i].voltage = 0.0f;
        modules[i].current = 0.0f;
        modules[i].duty_cycle = 500; // 初始50%占空比
        modules[i].integral = 0.0f;
        modules[i].voltage_ref = VOLTAGE_REF;
        modules[i].current_ref = CURRENT_SHARE_REF;
        write_pwm_duty(i, 500);
    }
    printf("Initialization Complete.\n");
}

// ==================== 主控制循环 ====================
static void control_loop(void) {
    // 更新所有模块的电压电流采样
    for (int i = 0; i < NUM_MODULES; i++) {
        modules[i].voltage = read_adc_voltage(i);
        modules[i].current = read_adc_current(i);
    }

    // 主从控制
    master_voltage_control();
    slave_current_share_control();

    // 同步标志置位（模拟）
    // WRITE_REG(SYNC_FLAG_ADDR, 0x01); // 注释掉避免访问非法内存
}

