// 模拟内存映射寄存器
static uint32_t mock_registers[0x100] = {0};

// 模拟寄存器地址映射
#define PWM_DUTY_A_REG       (uint32_t)(&mock_registers[0])
#define PWM_DUTY_B_REG       (uint32_t)(&mock_registers[1])
#define PWM_DUTY_C_REG       (uint32_t)(&mock_registers[2])
#define ADC_VOLTAGE_A_REG    (uint32_t)(&mock_registers[3])
#define ADC_VOLTAGE_B_REG    (uint32_t)(&mock_registers[4])
#define ADC_VOLTAGE_C_REG    (uint32_t)(&mock_registers[5])
#define ADC_CURRENT_A_REG    (uint32_t)(&mock_registers[6])
#define ADC_CURRENT_B_REG    (uint32_t)(&mock_registers[7])
#define ADC_CURRENT_C_REG    (uint32_t)(&mock_registers[8])

// 模拟寄存器读写宏
#define REG_READ(addr)       (*(volatile uint32_t *)(addr))
#define REG_WRITE(addr, val) (*(volatile uint32_t *)(addr) = (val))

// 坐标系变换结构体
typedef struct {
    float alpha;
    float beta;
} AlphaBeta;

typedef struct {
    float d;
    float q;
} DQ;

// 锁相环结构体
typedef struct {
    float theta;
    float omega;
    float delta_theta;
} PLL;

// 控制器状态
typedef struct {
    bool lvrt_active;
    float voltage_magnitude;
    float reactive_current_ref;
    float active_current_ref;
    PLL pll;
} LVRT_Controller;

// 全局控制器实例
LVRT_Controller g_ctrl = {0};

// 初始化锁相环
void PLL_Init(PLL *pll, float freq) {
    if (pll == NULL) return;
    pll->theta = 0.0f;
    pll->omega = 2.0f * PI * freq;
    pll->delta_theta = pll->omega * 0.0001f;
}

// 更新锁相环
void PLL_Update(PLL *pll) {
    if (pll == NULL) return;
    pll->theta += pll->delta_theta;
    if (pll->theta > 2.0f * PI) {
        pll->theta -= 2.0f * PI;
    }
    if (pll->theta < 0.0f) {
        pll->theta += 2.0f * PI;
    }
}

// Clarke变换
AlphaBeta Clarke(float a, float b, float c) {
    AlphaBeta ab;
    ab.alpha = (2.0f/3.0f) * (a - 0.5f * b - 0.5f * c);
    ab.beta  = (2.0f/3.0f) * (0.8660254f * b - 0.8660254f * c);
    return ab;
}

// Park变换
DQ Park(AlphaBeta ab, float theta) {
    DQ dq;
    dq.d =  ab.alpha * cosf(theta) + ab.beta * sinf(theta);
    dq.q = -ab.alpha * sinf(theta) + ab.beta * cosf(theta);
    return dq;
}

// 反Park变换
AlphaBeta InvPark(DQ dq, float theta) {
    AlphaBeta ab;
    ab.alpha = dq.d * cosf(theta) - dq.q * sinf(theta);
    ab.beta  = dq.d * sinf(theta) + dq.q * cosf(theta);
    return ab;
}

// 计算电压幅值
float CalcVoltageMagnitude(float va, float vb, float vc) {
    AlphaBeta ab = Clarke(va, vb, vc);
    float mag = sqrtf(ab.alpha * ab.alpha + ab.beta * ab.beta);
    if (GRID_NOMINAL_VOLTAGE > 0.0f) {
        return mag / GRID_NOMINAL_VOLTAGE;
    }
    return 0.0f;
}

// LVRT控制逻辑
void LVRT_Control(LVRT_Controller *ctrl, float va, float vb, float vc) {
    if (ctrl == NULL) return;

    ctrl->voltage_magnitude = CalcVoltageMagnitude(va, vb, vc);

    if (ctrl->voltage_magnitude < LVRT_THRESHOLD) {
        ctrl->lvrt_active = true;
    } else if (ctrl->voltage_magnitude > LVRT_RECOVERY_THRESH) {
        ctrl->lvrt_active = false;
    }

    if (ctrl->lvrt_active) {
        float voltage_drop = 1.0f - ctrl->voltage_magnitude;
        if (voltage_drop > 0.1f) voltage_drop = 0.1f;
        if (voltage_drop < 0.0f) voltage_drop = 0.0f;

        ctrl->reactive_current_ref = voltage_drop * 10.0f;

        float temp = 1.0f - ctrl->reactive_current_ref * ctrl->reactive_current_ref;
        if (temp > 0.0f) {
            ctrl->active_current_ref = sqrtf(temp);
        } else {
            ctrl->active_current_ref = 0.0f;
        }

        if (ctrl->active_current_ref > 1.0f) ctrl->active_current_ref = 1.0f;
    } else {
        ctrl->reactive_current_ref = 0.0f;
        ctrl->active_current_ref   = 1.0f;
    }
}

// PI控制器
float PI_Controller(float error, float kp, float ki, float *integral) {
    if (integral == NULL) return 0.0f;
    *integral += error * 0.0001f;
    return kp * error + ki * (*integral);
}

// 主控制循环
void ControlLoop(LVRT_Controller *ctrl) {
    if (ctrl == NULL) return;

    float va = REG_READ(ADC_VOLTAGE_A_REG) * 0.001f;
    float vb = REG_READ(ADC_VOLTAGE_B_REG) * 0.001f;
    float vc = REG_READ(ADC_VOLTAGE_C_REG) * 0.001f;
    float ia = REG_READ(ADC_CURRENT_A_REG) * 0.001f;
    float ib = REG_READ(ADC_CURRENT_B_REG) * 0.001f;
    float ic = REG_READ(ADC_CURRENT_C_REG) * 0.001f;

    PLL_Update(&ctrl->pll);
    LVRT_Control(ctrl, va, vb, vc);

    AlphaBeta ab_current = Clarke(ia, ib, ic);
    DQ dq_current = Park(ab_current, ctrl->pll.theta);

    static float id_integral = 0.0f;
    static float iq_integral = 0.0f;

    float vd_ref = PI_Controller(ctrl->active_current_ref - dq_current.d, 0.5f, 10.0f, &id_integral);
    float vq_ref = PI_Controller(ctrl->reactive_current_ref - dq_current.q, 0.5f, 10.0f, &iq_integral);

    AlphaBeta ab_ref = InvPark((DQ){vd_ref, vq_ref}, ctrl->pll.theta);
    float va_ref = ab_ref.alpha;
    float vb_ref = -0.5f * ab_ref.alpha + 0.8660254f * ab_ref.beta;
    float vc_ref = -0.5f * ab_ref.alpha - 0.8660254f * ab_ref.beta;

    REG_WRITE(PWM_DUTY_A_REG, (uint32_t)((va_ref + 1.0f) * 500.0f));
    REG_WRITE(PWM_DUTY_B_REG, (uint32_t)((vb_ref + 1.0f) * 500.0f));
    REG_WRITE(PWM_DUTY_C_REG, (uint32_t)((vc_ref + 1.0f) * 500.0f));
}

// 测试打印函数
void PrintStatus(LVRT_Controller *ctrl) {
    if (ctrl == NULL) return;
    printf("LVRT Status: %s\n", ctrl->lvrt_active ? "ACTIVE" : "INACTIVE");
    printf("Voltage Mag: %.3f pu\n", ctrl->voltage_magnitude);
    printf("Iq Ref: %.3f pu, Id Ref: %.3f pu\n", ctrl->reactive_current_ref, ctrl->active_current_ref);
    printf("PLL Theta: %.3f rad\n\n", ctrl->pll.theta);
}

int main() {
    printf("Grid-Tied Inverter LVRT Control Simulation\n");
    printf("==========================================\n\n");

    // 初始化控制器
    PLL_Init(&g_ctrl.pll, GRID_NOMINAL_FREQ);
    g_ctrl.lvrt_active = false;
    g_ctrl.voltage_magnitude = 1.0f;

    // 模拟运行10个控制周期
    for (int i = 0; i < 10; i++) {
        if (i >= 5) {
            REG_WRITE(ADC_VOLTAGE_A_REG, (uint32_t)(0.7f * GRID_NOMINAL_VOLTAGE * 1000.0f));
            REG_WRITE(ADC_VOLTAGE_B_REG, (uint32_t)(0.7f * GRID_NOMINAL_VOLTAGE * 1000.0f));
            REG_WRITE(ADC_VOLTAGE_C_REG, (uint32_t)(0.7f * GRID_NOMINAL_VOLTAGE * 1000.0f));
        } else {
            REG_WRITE(ADC_VOLTAGE_A_REG, (uint32_t)(GRID_NOMINAL_VOLTAGE * 1000.0f));
            REG_WRITE(ADC_VOLTAGE_B_REG, (uint32_t)(GRID_NOMINAL_VOLTAGE * 1000.0f));
            REG_WRITE(ADC_VOLTAGE_C_REG, (uint32_t)(GRID_NOMINAL_VOLTAGE * 1000.0f));
        }

        REG_WRITE(ADC_CURRENT_A_REG, 0);
        REG_WRITE(ADC_CURRENT_B_REG, 0);
        REG_WRITE(ADC_CURRENT_C_REG, 0);

        ControlLoop(&g_ctrl);

        printf("Cycle %d:\n", i+1);
        PrintStatus(&g_ctrl);
    }

    return 0;
}
