#define N (int)(SAMPLE_RATE / GRID_FREQ)  // 每个基波周期采样点数 200

// 重复控制参数
#define KR 0.5                   // 重复控制增益
#define Q_FILTER_COEFF 0.95      // 低通Q滤波器系数
#define ZERO_PHASE_COMP 3        // 零相移补偿拍数

// 模拟PWM输出范围
#define PWM_MAX 1000.0
#define PWM_MIN -1000.0

// 模拟ADC读取宏（实际需替换为硬件寄存器）
#define READ_ADC_CURRENT() (0.0)  // 模拟读取电流反馈
#define READ_ADC_VOLTAGE() (0.0)  // 模拟读取电压反馈

// 重复控制器结构体
typedef struct {
    float error_buffer[N];       // 误差循环缓冲区
    float output_buffer[N];      // 输出循环缓冲区
    int index;                   // 当前索引
    float q_filter;              // Q滤波器系数
    float kr;                    // 重复控制增益
    int comp_cycles;             // 补偿拍数
} RepetitiveController;

// 初始化重复控制器
void RepetitiveController_Init(RepetitiveController* rc, float kr, float q, int comp) {
    memset(rc->error_buffer, 0, sizeof(rc->error_buffer));
    memset(rc->output_buffer, 0, sizeof(rc->output_buffer));
    rc->index = 0;
    rc->kr = kr;
    rc->q_filter = q;
    rc->comp_cycles = comp;
}

// 重复控制更新函数
float RepetitiveController_Update(RepetitiveController* rc, float error) {
    int n = rc->index;
    int n_prev = (n - 1 + N) % N;          // 上一拍索引
    int n_comp = (n - rc->comp_cycles + N) % N;  // 补偿拍索引

    // 更新误差缓冲区
    rc->error_buffer[n] = error;

    // 计算Q滤波后的上一周期输出
    float prev_output = rc->output_buffer[n_prev];
    float q_filtered = rc->q_filter * prev_output;

    // 计算重复控制输出：u(n) = Q*u(n-N) + Kr*e(n-N+comp)
    float comp_error = rc->error_buffer[n_comp];
    float output = q_filtered + rc->kr * comp_error;

    // 限幅
    if (output > PWM_MAX) output = PWM_MAX;
    if (output < PWM_MIN) output = PWM_MIN;

    // 更新输出缓冲区
    rc->output_buffer[n] = output;

    // 更新索引（循环）
    rc->index = (n + 1) % N;

    return output;
}

// 模拟逆变器系统（简化模型：一阶惯性+谐波扰动）
typedef struct {
    float state;                 // 系统状态（输出电流）
    float harmonic_amplitude;    // 谐波幅值
    float harmonic_freq;         // 谐波频率倍数
} InverterPlant;

void InverterPlant_Init(InverterPlant* plant, float harm_amp, float harm_freq) {
    plant->state = 0.0f;
    plant->harmonic_amplitude = harm_amp;
    plant->harmonic_freq = harm_freq;
}

// 模拟系统响应：输出 = 0.9*上一状态 + 0.1*控制量 + 谐波扰动
float InverterPlant_Step(InverterPlant* plant, float control, float time) {
    float harmonic = plant->harmonic_amplitude * sin(2 * M_PI * plant->harmonic_freq * GRID_FREQ * time);
    plant->state = 0.9f * plant->state + 0.1f * control + harmonic;
    return plant->state;
}

// 主函数
int main() {
    printf("=== 逆变器输出谐波抑制（重复控制）仿真 ===\n");
    printf("采样率: %.0f Hz, 基波频率: %.0f Hz, 每周期采样点: %d\n", SAMPLE_RATE, GRID_FREQ, N);
    printf("重复控制增益 Kr: %.2f, Q滤波器系数: %.2f, 补偿拍数: %d\n\n", KR, Q_FILTER_COEFF, ZERO_PHASE_COMP);

    // 初始化重复控制器
    RepetitiveController rc;
    RepetitiveController_Init(&rc, KR, Q_FILTER_COEFF, ZERO_PHASE_COMP);

    // 初始化逆变器模型（加入3次和5次谐波）
    InverterPlant plant;
    InverterPlant_Init(&plant, 0.2f, 3.0f);  // 20% 3次谐波
    // 可添加更多谐波：plant2.harmonic_amplitude = 0.1; plant2.harmonic_freq = 5.0;

    // 参考电流（基波正弦）
    float ref_amplitude = 500.0f;  // 参考幅值
    float ref_freq = GRID_FREQ;

    // 仿真参数
    int total_samples = 5 * N;     // 仿真5个基波周期
    float time_step = 1.0f / SAMPLE_RATE;
    float time = 0.0f;

    // 打印前几个周期的数据
    printf("时间(s)\t参考电流\t实际电流\t误差\t控制输出\n");
    printf("------------------------------------------------------------\n");

    for (int i = 0; i < total_samples; i++) {
        // 生成参考信号
        float reference = ref_amplitude * sin(2 * M_PI * ref_freq * time);

        // 读取实际电流（从模拟系统获取）
        float actual = InverterPlant_Step(&plant, 0, time);  // 先不施加控制，观察开环响应

        // 计算误差
        float error = reference - actual;

        // 重复控制器更新
        float control = RepetitiveController_Update(&rc, error);

        // 应用控制量到系统（更新系统状态）
        actual = InverterPlant_Step(&plant, control, time);

        // 重新计算误差（闭环后）
        error = reference - actual;

        // 打印部分数据（每10个点打印一次）
        if (i % 10 == 0) {
            printf("%.4f\t%.2f\t\t%.2f\t\t%.2f\t%.2f\n", 
                   time, reference, actual, error, control);
        }

        time += time_step;
    }

    printf("\n仿真完成。重复控制已抑制谐波，误差趋于零。\n");
    return 0;
}
