// 模拟硬件寄存器定义 - 使用静态变量代替实际硬件地址
static uint32_t mock_pwm_duty = 0;
static uint32_t mock_adc_current = 0;
static uint32_t mock_timer_counter = 0;

#define PWM_DUTY_REGISTER  mock_pwm_duty
#define ADC_CURRENT_REGISTER mock_adc_current
#define TIMER_COUNTER_REGISTER mock_timer_counter

// 系统参数宏定义
#define CURRENT_LIMIT_THRESHOLD  10.0f   // 电流限幅阈值 (A)
#define CURRENT_LIMIT_MAX        12.0f   // 最大允许电流 (A)
#define PWM_PERIOD               1000    // PWM周期计数值
#define PWM_MAX_DUTY             950     // 最大占空比 (95%)
#define PWM_MIN_DUTY             50      // 最小占空比 (5%)
#define DUTY_STEP_DOWN           10      // 降载步进值
#define DUTY_STEP_UP             2       // 恢复步进值
#define CONTROL_CYCLE_MS         1       // 控制周期 (ms)

// 全局变量
static float current_measured = 0.0f;
static uint32_t current_duty = 500;      // 当前占空比 (50%初始值)
static bool overcurrent_flag = false;
static uint32_t overcurrent_count = 0;

// 模拟ADC读取函数
static float read_adc_current(void) {
    // 模拟电流采样值，实际应用中替换为ADC读取
    static float simulated_current = 5.0f;
    simulated_current += (float)(rand() % 100 - 50) * 0.1f;
    if (simulated_current < 0) simulated_current = 0;
    if (simulated_current > 15) simulated_current = 15;
    return simulated_current;
}

// 模拟PWM输出函数
static void set_pwm_duty(uint32_t duty) {
    if (duty > PWM_MAX_DUTY) duty = PWM_MAX_DUTY;
    if (duty < PWM_MIN_DUTY) duty = PWM_MIN_DUTY;
    PWM_DUTY_REGISTER = duty;
    current_duty = duty;
}

// 过流检测函数
static bool check_overcurrent(float current) {
    if (current > CURRENT_LIMIT_THRESHOLD) {
        overcurrent_count++;
        if (overcurrent_count >= 3) {  // 连续3次过流才触发保护
            return true;
        }
    } else {
        overcurrent_count = 0;
    }
    return false;
}

// 电流限幅控制函数
static void current_limiting_control(float current) {
    if (current > CURRENT_LIMIT_MAX) {
        // 严重过流，立即降载
        if (current_duty > DUTY_STEP_DOWN) {
            current_duty -= DUTY_STEP_DOWN;
        } else {
            current_duty = PWM_MIN_DUTY;
        }
        overcurrent_flag = true;
    } else if (current > CURRENT_LIMIT_THRESHOLD) {
        // 轻度过流，逐步降载
        if (current_duty > DUTY_STEP_DOWN) {
            current_duty -= DUTY_STEP_DOWN;
        } else {
            current_duty = PWM_MIN_DUTY;
        }
        overcurrent_flag = true;
    } else {
        // 正常电流范围，逐步恢复
        if (overcurrent_flag) {
            // 过流恢复阶段
            if (current_duty < PWM_MAX_DUTY) {
                current_duty += DUTY_STEP_UP;
            }
            if (current < CURRENT_LIMIT_THRESHOLD * 0.8f) {
                overcurrent_flag = false;  // 电流恢复正常，清除标志
            }
        } else {
            // 正常运行时缓慢调整到目标占空比
            if (current_duty < PWM_MAX_DUTY) {
                current_duty += DUTY_STEP_UP;
            }
        }
    }

    set_pwm_duty(current_duty);
}

// 主控制循环
static void inverter_control_loop(void) {
    // 读取当前电流
    current_measured = read_adc_current();

    // 过流检测
    bool oc = check_overcurrent(current_measured);

    // 执行电流限幅控制
    current_limiting_control(current_measured);

    // 打印调试信息
    printf("Current: %.2f A, Duty: %u, OC_Flag: %d\n", 
           current_measured, current_duty, oc);
}

int main(void) {
    printf("Inverter Overcurrent Limiting Control Demo\n");
    printf("==========================================\n");
    printf("Current Limit Threshold: %.1f A\n", CURRENT_LIMIT_THRESHOLD);
    printf("Current Max Limit: %.1f A\n", CURRENT_LIMIT_MAX);
    printf("PWM Period: %u\n\n", PWM_PERIOD);

    // 初始化PWM输出
    set_pwm_duty(current_duty);
    printf("Initial PWM Duty: %u\n\n", current_duty);

    // 模拟控制循环运行100个周期
    for (int cycle = 0; cycle < 100; cycle++) {
        printf("Cycle %3d: ", cycle);
        inverter_control_loop();

        // 模拟控制周期延时
        for (volatile uint32_t delay = 0; delay < 100000; delay++);
    }

    printf("\nControl loop completed.\n");
    return 0;
}
