    bool zero_cross_detected;   // 过零检测标志
} SwitchController;

// ==================== 模拟硬件初始化 ====================
void hardware_init(void) {
    // 初始化所有模拟寄存器
    REG_ADC_GRID_VOLTAGE = 2200;      // 市电正常
    REG_ADC_INVERTER_VOLTAGE = 2200;  // 逆变器待机
    REG_ADC_LOAD_VOLTAGE = 2200;      // 负载电压
    REG_PWM_INVERTER_ENABLE = 0;
    REG_PWM_GRID_ENABLE = 1;
    REG_GPIO_RELAY_GRID = 1;          // 市电继电器闭合
    REG_GPIO_RELAY_INVERTER = 0;      // 逆变继电器断开
    REG_TIMER_CAPTURE = 0;
    REG_TIMER_COMPARE = 1000;         // 模拟50Hz周期 (20ms)
}

// ==================== 模拟ADC读取 ====================
void read_voltages(VoltageData *data) {
    if (data == NULL) return;
    data->grid_voltage = (float)REG_ADC_GRID_VOLTAGE / 10.0f;
    data->inverter_voltage = (float)REG_ADC_INVERTER_VOLTAGE / 10.0f;
    data->load_voltage = (float)REG_ADC_LOAD_VOLTAGE / 10.0f;
}

// ==================== 过零检测 ====================
bool detect_zero_crossing(VoltageData *data) {
    if (data == NULL) return false;
    static float prev_grid_voltage = 0;
    bool zero_cross = false;

    // 检测市电电压从正到负的过零点
    if (prev_grid_voltage > 0 && data->grid_voltage <= 0) {
        zero_cross = true;
    }
    prev_grid_voltage = data->grid_voltage;

    return zero_cross;
}

// ==================== 锁相环 (PLL) ====================
void update_pll(VoltageData *data, SwitchController *ctrl) {
    if (data == NULL || ctrl == NULL) return;

    // 模拟市电相位更新 (50Hz)
    static float grid_phase = 0;
    grid_phase += TWO_PI * 50.0f * (SAMPLE_INTERVAL_US / 1000000.0f);
    if (grid_phase > TWO_PI) grid_phase -= TWO_PI;
    data->grid_phase = grid_phase;

    // 计算相位误差
    data->phase_error = data->grid_phase - ctrl->current_phase;
    if (data->phase_error > PI) data->phase_error -= TWO_PI;
    if (data->phase_error < -PI) data->phase_error += TWO_PI;

    // 更新逆变器相位 (锁相)
    ctrl->current_phase += PHASE_LOCK_LOOP_GAIN * data->phase_error;
    if (ctrl->current_phase > TWO_PI) ctrl->current_phase -= TWO_PI;
    if (ctrl->current_phase < 0) ctrl->current_phase += TWO_PI;

    data->inverter_phase = ctrl->current_phase;
}

// ==================== 市电质量检测 ====================
bool is_grid_stable(VoltageData *data) {
    if (data == NULL) return false;
    float grid = data->grid_voltage;
    float nominal = GRID_NOMINAL_VOLTAGE / 10.0f;
    float tolerance = nominal * GRID_TOLERANCE_PERCENT / 100.0f;

    return (grid >= (nominal - tolerance)) && (grid <= (nominal + tolerance));
}

// ==================== 切换控制核心算法 ====================
void switch_control(SwitchController *ctrl, VoltageData *data) {
    if (ctrl == NULL || data == NULL) return;

    bool grid_ok = is_grid_stable(data);
    bool zero_cross = detect_zero_crossing(data);

    switch (ctrl->current_mode) {
        case MODE_GRID:
            if (!grid_ok) {
                // 市电异常，准备切换到逆变
                ctrl->current_mode = MODE_TRANSITION;
                ctrl->transition_timer = 0;
                ctrl->target_phase = data->grid_phase;
                printf("[SWITCH] Grid fail -> Transition start\n");
            }
            break;

        case MODE_INVERTER:
            if (grid_ok && zero_cross) {
                // 市电恢复且过零，准备切回市电
                ctrl->current_mode = MODE_TRANSITION;
                ctrl->transition_timer = 0;
                ctrl->target_phase = data->grid_phase;
                printf("[SWITCH] Grid restore -> Transition start\n");
            }
            break;

        case MODE_TRANSITION:
            ctrl->transition_timer += SAMPLE_INTERVAL_US / 1000;

            // 相位同步控制
            float phase_diff = ctrl->target_phase - ctrl->current_phase;
            if (phase_diff > PI) phase_diff -= TWO_PI;
            if (phase_diff < -PI) phase_diff += TWO_PI;

            // 逐步调整相位
            ctrl->current_phase += 0.5f * phase_diff;
            if (ctrl->current_phase > TWO_PI) ctrl->current_phase -= TWO_PI;
            if (ctrl->current_phase < 0) ctrl->current_phase += TWO_PI;

            // 检查过渡完成条件
            if (ctrl->transition_timer >= SWITCH_TRANSITION_TIME_MS) {
                if (grid_ok) {
                    // 切回市电
                    REG_PWM_INVERTER_ENABLE = 0;
                    REG_PWM_GRID_ENABLE = 1;
                    REG_GPIO_RELAY_INVERTER = 0;
                    REG_GPIO_RELAY_GRID = 1;
                    ctrl->current_mode = MODE_GRID;
                    printf("[SWITCH] Transition complete -> Grid mode\n");
                } else {
                    // 切换到逆变
                    REG_PWM_GRID_ENABLE = 0;
                    REG_PWM_INVERTER_ENABLE = 1;
                    REG_GPIO_RELAY_GRID = 0;
                    REG_GPIO_RELAY_INVERTER = 1;
                    ctrl->current_mode = MODE_INVERTER;
                    printf("[SWITCH] Transition complete -> Inverter mode\n");
                }
            }
            break;
    }
}

// ==================== 主函数 ====================
int main(void) {
    // 初始化
    hardware_init();

    VoltageData voltage_data = {0};
    SwitchController controller = {
        .current_mode = MODE_GRID,
        .transition_timer = 0,
        .target_phase = 0,
        .current_phase = 0,
        .zero_cross_detected = false
    };

    printf("=== UPS Inverter Zero-Crossing Switch Control ===\n");
    printf("Initial mode: Grid\n\n");

    // 模拟运行循环 (100次迭代)
    for (int i = 0; i < 100; i++) {
        // 读取电压数据
        read_voltages(&voltage_data);

        // 更新锁相环
        update_pll(&voltage_data, &controller);

        // 执行切换控制
        switch_control(&controller, &voltage_data);

        // 打印状态信息
        printf("Iter %3d: Mode=%d, Vgrid=%.1fV, Vload=%.1fV, PhaseErr=%.3f rad\n",
               i, controller.current_mode,
               voltage_data.grid_voltage,
               voltage_data.load_voltage,
               voltage_data.phase_error);

        // 模拟市电故障 (第30次迭代)
        if (i == 30) {
            REG_ADC_GRID_VOLTAGE = 1500;  // 市电电压跌落到150V
            printf(">>> Grid fault simulated!\n");
        }

        // 模拟市电恢复 (第70次迭代)
        if (i == 70) {
            REG_ADC_GRID_VOLTAGE = 2200;  // 市电恢复正常
            printf(">>> Grid restored!\n");
        }

        // 模拟采样间隔
        // 实际系统中这里会使用定时器延时
    }

    printf("\n=== Simulation Complete ===\n");
    return 0;
}
