static uint32_t mock_reg_timer_capture_value = 0;
static uint32_t mock_reg_timer_sync_reset = 0;

// ==================== 系统参数配置 ====================
#define GRID_NOMINAL_VOLTAGE      2200   // 电网额定电压 (0.1V单位，即220.0V)
#define GRID_TOLERANCE_PERCENT    10     // 电网电压容差百分比
#define INVERTER_NOMINAL_VOLTAGE  2200   // 逆变器额定电压
#define PHASE_LOCK_THRESHOLD      50     // 锁相环角度误差阈值 (0.1度)
#define SWITCH_TRANSITION_TIME    100    // 切换过渡时间 (us)

// ==================== 状态枚举 ====================
typedef enum {
    UPS_STATE_GRID = 0,       // 市电供电
    UPS_STATE_INVERTER,       // 逆变器供电
    UPS_STATE_TRANSITION      // 切换过渡中
} UPS_State_t;

// ==================== 数据结构 ====================
typedef struct {
    uint32_t grid_voltage;        // 电网电压采样值
    uint32_t inverter_voltage;    // 逆变器输出电压采样值
    uint32_t load_voltage;        // 负载电压采样值
    int32_t  phase_error;         // 相位误差 (0.1度)
    uint32_t zero_cross_count;    // 过零计数
    bool     grid_ok;             // 电网状态标志
} UPS_SensorData_t;

typedef struct {
    UPS_State_t current_state;
    uint32_t    transition_timer;
    uint32_t    pwm_phase_shift;
    bool        grid_relay_on;
    bool        inverter_relay_on;
} UPS_Control_t;

// ==================== 全局变量 ====================
static UPS_SensorData_t sensor_data = {0};
static UPS_Control_t    control = {UPS_STATE_GRID, 0, 0, true, false};

// ==================== 模拟硬件初始化 ====================
static void HW_Init(void) {
    // 初始化模拟寄存器
    mock_reg_adc_grid_voltage = 2200;
    mock_reg_adc_inverter_voltage = 0;
    mock_reg_adc_load_voltage = 2200;
    mock_reg_pwm_inverter_enable = 0;
    mock_reg_pwm_grid_enable = 1;
    mock_reg_pwm_phase_shift = 0;
    mock_reg_gpio_relay_grid = 1;
    mock_reg_gpio_relay_inverter = 0;
    mock_reg_timer_capture_value = 0;
    mock_reg_timer_sync_reset = 0;

    printf("UPS System Initialized (Grid Mode)\n");
}

// ==================== 模拟ADC采样 ====================
static void ADC_Sample(void) {
    sensor_data.grid_voltage = mock_reg_adc_grid_voltage;
    sensor_data.inverter_voltage = mock_reg_adc_inverter_voltage;
    sensor_data.load_voltage = mock_reg_adc_load_voltage;
}

// ==================== 电网质量检测 ====================
static bool Check_Grid_Quality(void) {
    uint32_t voltage_error;

    if (sensor_data.grid_voltage > GRID_NOMINAL_VOLTAGE) {
        voltage_error = sensor_data.grid_voltage - GRID_NOMINAL_VOLTAGE;
    } else {
        voltage_error = GRID_NOMINAL_VOLTAGE - sensor_data.grid_voltage;
    }

    uint32_t tolerance = (GRID_NOMINAL_VOLTAGE * GRID_TOLERANCE_PERCENT) / 100;
    return (voltage_error <= tolerance);
}

// ==================== 锁相环 (PLL) 模拟 ====================
static void PLL_Sync(void) {
    static uint32_t last_capture = 0;
    uint32_t current_capture = mock_reg_timer_capture_value;

    if (current_capture != last_capture) {
        sensor_data.zero_cross_count++;

        int32_t phase_diff = (int32_t)(mock_reg_pwm_phase_shift) - 1800;
        if (phase_diff < 0) {
            sensor_data.phase_error = -phase_diff;
        } else {
            sensor_data.phase_error = phase_diff;
        }

        last_capture = current_capture;
    }
}

// ==================== 零中断切换核心算法 ====================
static void Zero_Cross_Switch(void) {
    bool grid_quality = Check_Grid_Quality();

    if (grid_quality && !sensor_data.grid_ok) {
        printf("Grid recovered, preparing switch back\n");
        sensor_data.grid_ok = true;
    } else if (!grid_quality && sensor_data.grid_ok) {
        printf("Grid failure detected, initiating inverter switch\n");
        sensor_data.grid_ok = false;
    }

    switch (control.current_state) {
        case UPS_STATE_GRID:
            if (!sensor_data.grid_ok) {
                control.current_state = UPS_STATE_TRANSITION;
                control.transition_timer = SWITCH_TRANSITION_TIME;

                mock_reg_pwm_inverter_enable = 1;
                mock_reg_pwm_phase_shift = 0;

                printf("Transition to inverter started\n");
            }
            break;

        case UPS_STATE_INVERTER:
            if (sensor_data.grid_ok) {
                control.current_state = UPS_STATE_TRANSITION;
                control.transition_timer = SWITCH_TRANSITION_TIME;

                mock_reg_pwm_phase_shift = 1800;

                printf("Transition to grid started\n");
            }
            break;

        case UPS_STATE_TRANSITION:
            if (control.transition_timer > 0) {
                control.transition_timer--;

                if (sensor_data.phase_error < PHASE_LOCK_THRESHOLD) {
                    if (!sensor_data.grid_ok) {
                        mock_reg_gpio_relay_grid = 0;
                        mock_reg_gpio_relay_inverter = 1;
                        mock_reg_pwm_grid_enable = 0;

                        control.current_state = UPS_STATE_INVERTER;
                        printf("Switched to inverter mode\n");
                    } else {
                        mock_reg_gpio_relay_inverter = 0;
                        mock_reg_gpio_relay_grid = 1;
                        mock_reg_pwm_grid_enable = 1;
                        mock_reg_pwm_inverter_enable = 0;

                        control.current_state = UPS_STATE_GRID;
                        printf("Switched to grid mode\n");
                    }
                }
            } else {
                printf("Transition timeout, forcing switch\n");
                if (!sensor_data.grid_ok) {
                    mock_reg_gpio_relay_grid = 0;
                    mock_reg_gpio_relay_inverter = 1;
                    control.current_state = UPS_STATE_INVERTER;
                } else {
                    mock_reg_gpio_relay_inverter = 0;
                    mock_reg_gpio_relay_grid = 1;
                    control.current_state = UPS_STATE_GRID;
                }
            }
            break;
    }
}

// ==================== 主控制循环 ====================
static void UPS_Control_Loop(void) {
    ADC_Sample();
    PLL_Sync();
    Zero_Cross_Switch();

    if (control.current_state == UPS_STATE_GRID) {
        mock_reg_adc_load_voltage = sensor_data.grid_voltage;
    } else if (control.current_state == UPS_STATE_INVERTER) {
        mock_reg_adc_load_voltage = sensor_data.inverter_voltage;
    }
