#define TIM1_CCR1 mock_tim1_ccr1
#define TIM1_CCR2 mock_tim1_ccr2
#define TIM1_CCR3 mock_tim1_ccr3
#define TIM2_ARR  mock_tim2_arr
#define TIM2_CCR1 mock_tim2_ccr1
#define TIM2_CCR2 mock_tim2_ccr2
#define TIM2_CCR3 mock_tim2_ccr3
#define TIM3_ARR  mock_tim3_arr
#define TIM3_CCR1 mock_tim3_ccr1
#define TIM3_CCR2 mock_tim3_ccr2
#define TIM3_CCR3 mock_tim3_ccr3

// 系统参数
#define CARRIER_FREQ_HZ     20000   // 载波频率20kHz
#define SAMPLE_FREQ_HZ      200000  // 采样频率200kHz
#define GRID_FREQ_HZ        50      // 基波频率50Hz
#define NUM_CELLS           3       // 级联H桥单元数
#define PI                  3.14159265358979323846

// 全局变量
static float phase_shift = 0.0f;           // 载波移相角（弧度）
static float sin_table[256];               // 正弦表
static uint16_t carrier_counter[NUM_CELLS]; // 各单元载波计数器
static uint16_t carrier_period;            // 载波周期（采样点数）

// 初始化正弦表
static void init_sin_table(void) {
    for (int i = 0; i < 256; i++) {
        sin_table[i] = sinf(2.0f * PI * i / 256.0f);
    }
}

// 初始化载波参数
static void init_carrier(void) {
    carrier_period = SAMPLE_FREQ_HZ / CARRIER_FREQ_HZ;
    phase_shift = 2.0f * PI / NUM_CELLS;  // 各单元载波移相120度

    for (int i = 0; i < NUM_CELLS; i++) {
        carrier_counter[i] = (uint16_t)(i * carrier_period / NUM_CELLS);
    }
}

// 模拟PWM比较器更新
static void update_pwm_comparator(uint8_t cell_index, float duty) {
    uint16_t compare_value = (uint16_t)(duty * carrier_period);

    switch (cell_index) {
        case 0:
            TIM1_CCR1 = compare_value;
            break;
        case 1:
            TIM2_CCR1 = compare_value;
            break;
        case 2:
            TIM3_CCR1 = compare_value;
            break;
        default:
            break;
    }
}

// 载波移相调制核心算法
static void phase_shift_carrier_modulation(float modulation_index) {
    static uint32_t sample_count = 0;
    float mod_signal;
    float duty_cycle;

    // 生成调制波（50Hz正弦波）
    uint32_t samples_per_cycle = SAMPLE_FREQ_HZ / GRID_FREQ_HZ;
    if (samples_per_cycle == 0) return; // 防止除零

    uint8_t table_index = (uint8_t)((sample_count * 256) / samples_per_cycle);
    mod_signal = sin_table[table_index] * modulation_index;

    // 对各单元进行载波移相调制
    for (int i = 0; i < NUM_CELLS; i++) {
        // 更新载波计数器（三角波）
        carrier_counter[i]++;
        if (carrier_counter[i] >= carrier_period) {
            carrier_counter[i] = 0;
        }

        // 计算占空比（双极性调制）
        float carrier = 2.0f * carrier_counter[i] / carrier_period - 1.0f;
        if (mod_signal > carrier) {
            duty_cycle = 1.0f;  // 正电平
        } else {
            duty_cycle = 0.0f;  // 负电平
        }

        // 更新PWM比较器
        update_pwm_comparator(i, duty_cycle);
    }

    sample_count++;
}

// 模拟定时器中断服务函数
void timer_interrupt_handler(void) {
    // 实际应用中在此处调用调制算法
    phase_shift_carrier_modulation(0.8f);  // 调制比0.8
}

int main(void) {
    // 初始化
    init_sin_table();
    init_carrier();

    printf("载波移相调制系统初始化完成\n");
    printf("载波频率: %d Hz\n", CARRIER_FREQ_HZ);
    printf("采样频率: %d Hz\n", SAMPLE_FREQ_HZ);
    printf("级联单元数: %d\n", NUM_CELLS);
    printf("载波移相角: %.2f 度\n", phase_shift * 180.0f / PI);

    // 模拟运行10个采样周期
    for (int i = 0; i < 10; i++) {
        timer_interrupt_handler();

        // 打印当前状态
        printf("采样点 %d: 载波计数器=[%d,%d,%d], CCR=[%u,%u,%u]\n",
               i,
               carrier_counter[0], carrier_counter[1], carrier_counter[2],
               (unsigned int)TIM1_CCR1, (unsigned int)TIM2_CCR1, (unsigned int)TIM3_CCR1);
    }

    printf("多电平输出验证完成\n");
    return 0;
}
