    {-2.0/3.0*VDC, 1.0/3.0*VDC, 1.0/3.0*VDC},  // V4 (011)
    {-1.0/3.0*VDC, -1.0/3.0*VDC, 2.0/3.0*VDC}, // V5 (001)
    {1.0/3.0*VDC, -2.0/3.0*VDC, 1.0/3.0*VDC},  // V6 (101)
    {0, 0, 0}            // V7 (111)
};

// 三相电流状态
typedef struct {
    double ia;
    double ib;
    double ic;
} CurrentState;

// 三相参考电流
typedef struct {
    double ia_ref;
    double ib_ref;
    double ic_ref;
} CurrentReference;

// 预测下一时刻电流 (基于欧拉离散化)
CurrentState predict_current(const CurrentState* current, const VoltageVector* v, double ts) {
    CurrentState next;
    // 三相独立预测 (假设中性点隔离，实际需考虑耦合，这里简化)
    next.ia = current->ia + (ts / L) * (v->va - R * current->ia);
    next.ib = current->ib + (ts / L) * (v->vb - R * current->ib);
    next.ic = current->ic + (ts / L) * (v->vc - R * current->ic);
    return next;
}

// 计算成本函数 (跟踪误差平方和)
double cost_function(const CurrentState* predicted, const CurrentReference* ref) {
    double err_a = predicted->ia - ref->ia_ref;
    double err_b = predicted->ib - ref->ib_ref;
    double err_c = predicted->ic - ref->ic_ref;
    return err_a * err_a + err_b * err_b + err_c * err_c;
}

// 模型预测控制主函数 (返回最优开关状态索引)
int mpc_control(const CurrentState* current, const CurrentReference* ref) {
    int best_idx = 0;
    double min_cost = 1e10;

    for (int i = 0; i < 8; i++) {
        CurrentState predicted = predict_current(current, &voltage_vectors[i], TS);
        double cost = cost_function(&predicted, ref);
        if (cost < min_cost) {
            min_cost = cost;
            best_idx = i;
        }
    }
    return best_idx;
}

int main() {
    // 初始化当前电流和参考电流
    CurrentState current = {0.0, 0.0, 0.0};
    CurrentReference ref = {10.0, -5.0, -5.0}; // 三相平衡参考

    printf("逆变器模型预测控制 (单步成本函数优化) 演示\n");
    printf("直流母线电压: %.1f V\n", VDC);
    printf("滤波电感: %.4f H\n", L);
    printf("电阻: %.2f Ohm\n", R);
    printf("采样周期: %.6f s\n\n", TS);

    // 模拟几个控制周期
    for (int step = 0; step < 5; step++) {
        int opt_idx = mpc_control(&current, &ref);
        VoltageVector opt_v = voltage_vectors[opt_idx];
        CurrentState next = predict_current(&current, &opt_v, TS);

        printf("步骤 %d:\n", step + 1);
        printf("  当前电流: ia=%.3f, ib=%.3f, ic=%.3f\n", current.ia, current.ib, current.ic);
        printf("  参考电流: ia_ref=%.3f, ib_ref=%.3f, ic_ref=%.3f\n", ref.ia_ref, ref.ib_ref, ref.ic_ref);
        printf("  最优开关状态索引: %d (电压: va=%.1f, vb=%.1f, vc=%.1f)\n", opt_idx, opt_v.va, opt_v.vb, opt_v.vc);
        printf("  预测下一时刻电流: ia=%.3f, ib=%.3f, ic=%.3f\n\n", next.ia, next.ib, next.ic);

        // 更新当前电流为预测值 (模拟闭环)
        current = next;
    }

    return 0;
}
