// 锁相环结构体
typedef struct {
    float theta;
    float omega;
    float phase_error;
} PLL_t;

// 功率因数控制器
typedef struct {
    float integral;
    float output;
    float ref_pf;
} PF_Controller_t;

// 全局变量
static PLL_t pll = {0.0f, 2*PI*GRID_FREQ, 0.0f};
static PF_Controller_t pf_ctrl = {0.0f, 0.0f, TARGET_PF};

// 锁相环更新
void pll_update(float grid_angle) {
    pll.phase_error = grid_angle - pll.theta;
    // 简单PLL
    pll.omega = 2*PI*GRID_FREQ + 100.0f * pll.phase_error;
    pll.theta += pll.omega / SAMPLE_FREQ;
    if(pll.theta > 2*PI) pll.theta -= 2*PI;
}

// 计算功率因数
float calculate_pf(float voltage, float current, float angle) {
    float active_power = voltage * current * cosf(angle);
    float apparent_power = voltage * current;
    if(apparent_power < 0.001f) return 1.0f;
    return fabsf(active_power / apparent_power);
}

// PI控制器
float pi_controller(PF_Controller_t *ctrl, float error) {
    ctrl->integral += error * KI / SAMPLE_FREQ;
    // 积分限幅
    if(ctrl->integral > 1.0f) ctrl->integral = 1.0f;
    if(ctrl->integral < -1.0f) ctrl->integral = -1.0f;
    return KP * error + ctrl->integral;
}

// 主控制函数
void power_factor_control(void) {
    float voltage = read_adc_voltage();
    float current = read_adc_current();
    float grid_angle = read_adc_grid_angle();

    // 更新锁相环
    pll_update(grid_angle);

    // 计算当前功率因数
    float current_pf = calculate_pf(voltage, current, pll.theta);

    // 计算误差
    float pf_error = pf_ctrl.ref_pf - current_pf;

    // PI控制
    float control_output = pi_controller(&pf_ctrl, pf_error);

    // 限制输出范围
    if(control_output > 0.95f) control_output = 0.95f;
    if(control_output < 0.0f) control_output = 0.0f;

    // 更新PWM占空比
    write_pwm_duty(control_output);

