#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// 模拟的逆变器控制参数
#define SAMPLE_FREQ 10000.0f       // 采样频率 10kHz
#define DT (1.0f / SAMPLE_FREQ)    // 采样周期
#define PI 3.141592653589793f

// 逆变器电气参数（模拟）
#define L_INV 0.001f               // 逆变器侧电感 1mH
#define C_FILTER 10e-6f            // 滤波电容 10uF
#define R_DAMP_TARGET 0.5f         // 目标阻尼电阻 0.5Ω

// 虚拟阻抗参数（用于重塑输出阻抗）
#define VIRTUAL_RESISTANCE 0.5f    // 虚拟电阻 Rv
#define VIRTUAL_INDUCTANCE 0.0005f // 虚拟电感 Lv (0.5mH)

// 控制环路状态变量
typedef struct {
    float iL_prev;      // 上一拍电感电流
    float vC_prev;      // 上一拍电容电压
    float vC_filtered;  // 滤波后的电容电压（用于虚拟阻抗计算）
    float iL_filtered;  // 滤波后的电感电流
} InverterState;

// 模拟ADC读取函数（返回模拟值）
float mock_adc_read_voltage(void) {
    // 模拟220Vrms正弦波 + 谐波干扰
    static float phase = 0.0f;
    phase += 2.0f * PI * 50.0f * DT;
    if (phase > 2.0f * PI) phase -= 2.0f * PI;
    float fundamental = 311.0f * sinf(phase);  // 311V peak
    float harmonic3 = 30.0f * sinf(3.0f * phase); // 3次谐波
    return fundamental + harmonic3;
}

float mock_adc_read_current(void) {
    // 模拟负载电流（阻性负载+谐波）
    static float phase = 0.0f;
    phase += 2.0f * PI * 50.0f * DT;
    if (phase > 2.0f * PI) phase -= 2.0f * PI;
    float fundamental = 10.0f * sinf(phase);  // 10A peak
    float harmonic5 = 2.0f * sinf(5.0f * phase); // 5次谐波
    return fundamental + harmonic5;
}

// 一阶低通滤波器（用于虚拟阻抗计算中的微分近似）
float low_pass_filter(float input, float prev_output, float cutoff_freq) {
    float tau = 1.0f / (2.0f * PI * cutoff_freq);
    float alpha = DT / (tau + DT);
    return alpha * input + (1.0f - alpha) * prev_output;
}

// 核心算法：输出阻抗重塑（阻尼注入）
// 通过虚拟电阻和虚拟电感串联来重塑逆变器输出阻抗
// 输出：修正后的电压参考值
float impedance_shaping_control(float v_meas, float i_meas, InverterState *state) {
    // 1. 对测量值进行低通滤波（去除高频噪声）
    float v_filtered = low_pass_filter(v_meas, state->vC_filtered, 500.0f);  // 500Hz截止
    float i_filtered = low_pass_filter(i_meas, state->iL_filtered, 500.0f);

    // 2. 计算虚拟阻抗上的压降
    // 虚拟阻抗 Zv = Rv + s*Lv
    // 压降 Vz = Rv * iL + Lv * diL/dt
    // 使用后向欧拉法近似微分：diL/dt ≈ (iL - iL_prev) / DT
    float diL_dt = (i_filtered - state->iL_prev) / DT;
    float v_drop = VIRTUAL_RESISTANCE * i_filtered + VIRTUAL_INDUCTANCE * diL_dt;

    // 3. 计算修正后的电压参考值
    // 原始参考电压为电容电压，通过减去虚拟阻抗压降实现阻抗重塑
    float v_ref_corrected = v_filtered - v_drop;

    // 4. 更新状态变量
    state->vC_filtered = v_filtered;
    state->iL_filtered = i_filtered;
    state->iL_prev = i_filtered;
    state->vC_prev = v_filtered;

    return v_ref_corrected;
}

// 模拟PWM占空比生成（简化）
float generate_pwm_duty(float v_ref, float v_dc) {
    // 假设直流母线电压400V，输出占空比 = v_ref / v_dc
    float duty = v_ref / v_dc;
    // 限幅
    if (duty > 0.95f) duty = 0.95f;
    if (duty < -0.95f) duty = -0.95f;
    return duty;
}

int main() {
    printf("=== 逆变器输出阻抗重塑（阻尼注入）控制算法测试 ===\n\n");

    // 初始化状态
    InverterState state = {0};
    float v_dc = 400.0f;  // 直流母线电压

    // 运行100个控制周期
    for (int i = 0; i < 100; i++) {
        // 模拟采样
        float v_meas = mock_adc_read_voltage();
        float i_meas = mock_adc_read_current();

        // 执行阻抗重塑控制
        float v_ref_corrected = impedance_shaping_control(v_meas, i_meas, &state);

        // 生成PWM占空比
        float duty = generate_pwm_duty(v_ref_corrected, v_dc);

        // 每10个周期打印一次结果
        if (i % 10 == 0) {
            printf("周期 %3d: 测量电压=%.2fV, 测量电流=%.2fA, 修正参考电压=%.2fV, 占空比=%.4f\n",
                   i, v_meas, i_meas, v_ref_corrected, duty);
        }
    }

    printf("\n算法执行完毕。\n");
    printf("虚拟阻抗参数: Rv=%.3fΩ, Lv=%.5fH\n", VIRTUAL_RESISTANCE, VIRTUAL_INDUCTANCE);
    printf("目标阻尼电阻: %.2fΩ\n", R_DAMP_TARGET);

    return 0;
}
