typedef unsigned int uint32_t;

// 模拟硬件寄存器 - 使用静态变量代替指针
static uint32_t mock_pwm_reg = 0;
static uint32_t mock_adc_voltage_reg = 0;
static uint32_t mock_adc_current_reg = 0;

// 宏定义：模拟寄存器读写
#define REG_WRITE(addr, val) do { \
    if ((addr) == 0x4000) mock_pwm_reg = (val); \
    else if ((addr) == 0x4004) mock_adc_voltage_reg = (val); \
    else if ((addr) == 0x4008) mock_adc_current_reg = (val); \
} while(0)

#define REG_READ(addr) ((addr) == 0x4000 ? mock_pwm_reg : \
                       ((addr) == 0x4004 ? mock_adc_voltage_reg : \
                       ((addr) == 0x4008 ? mock_adc_current_reg : 0)))

// 系统参数
#define SAMPLE_FREQ 10000.0f       // 10kHz采样频率
#define DT (1.0f / SAMPLE_FREQ)    // 采样周期
#define VDC 400.0f                 // 直流母线电压
#define L_FILTER 2.0e-3f           // 滤波电感 2mH
#define C_FILTER 10.0e-6f          // 滤波电容 10uF
#define R_DAMP 2.0f                // 虚拟阻尼电阻

// 控制器状态变量
typedef struct {
    float v_out;           // 输出电压采样值
    float i_out;           // 输出电流采样值
    float v_ref;           // 电压参考值
    float i_damp;          // 阻尼电流
    float duty_cycle;      // 占空比输出
    float v_out_filtered;  // 滤波后的输出电压
    float i_out_filtered;  // 滤波后的输出电流
} InverterState;

// 初始化逆变器状态
void inverter_init(InverterState *state) {
    if (state == NULL) return;
    state->v_out = 0.0f;
    state->i_out = 0.0f;
    state->v_ref = 220.0f;  // 220V参考电压
    state->i_damp = 0.0f;
    state->duty_cycle = 0.5f;  // 初始50%占空比
    state->v_out_filtered = 0.0f;
    state->i_out_filtered = 0.0f;
}

// 一阶低通滤波器
float low_pass_filter(float input, float prev_output, float cutoff_freq) {
    if (cutoff_freq <= 0.0f) return input;
    float tau = 1.0f / (2.0f * M_PI * cutoff_freq);
    float alpha = DT / (tau + DT);
    return alpha * input + (1.0f - alpha) * prev_output;
}

// 虚拟阻抗阻尼注入算法
void impedance_damping(InverterState *state) {
    if (state == NULL) return;

    // 1. 读取ADC采样值（模拟）
    state->v_out = (float)REG_READ(0x4004) * 0.1f;  // 模拟电压转换
    state->i_out = (float)REG_READ(0x4008) * 0.01f; // 模拟电流转换

    // 2. 低通滤波（截止频率1kHz）
    state->v_out_filtered = low_pass_filter(state->v_out, state->v_out_filtered, 1000.0f);
    state->i_out_filtered = low_pass_filter(state->i_out, state->i_out_filtered, 1000.0f);

    // 3. 计算阻尼电流：i_damp = (v_ref - v_out) / R_damp
    if (R_DAMP > 0.0f) {
        state->i_damp = (state->v_ref - state->v_out_filtered) / R_DAMP;
    } else {
        state->i_damp = 0.0f;
    }

    // 4. 计算总电流参考（包含阻尼分量）
    float i_ref_total = state->i_damp;

    // 5. 电流环PI控制（简化比例控制）
    float current_error = i_ref_total - state->i_out_filtered;
    float voltage_command = current_error * 10.0f;  // 比例增益

    // 6. 限制电压指令范围
    if (voltage_command > VDC) voltage_command = VDC;
    if (voltage_command < -VDC) voltage_command = -VDC;

    // 7. 转换为占空比
    state->duty_cycle = (voltage_command / VDC) * 0.5f + 0.5f;

    // 8. 限制占空比范围
    if (state->duty_cycle > 0.95f) state->duty_cycle = 0.95f;
    if (state->duty_cycle < 0.05f) state->duty_cycle = 0.05f;

    // 9. 写入PWM寄存器
    REG_WRITE(0x4000, (uint32_t)(state->duty_cycle * 1000.0f));
}

int main() {
    InverterState inverter;
    inverter_init(&inverter);

    printf("逆变器输出阻抗重塑（阻尼注入）算法测试\n");
    printf("系统参数：\n");
    printf("  采样频率: %.0f Hz\n", SAMPLE_FREQ);
    printf("  直流母线电压: %.1f V\n", VDC);
    printf("  滤波电感: %.3f mH\n", L_FILTER * 1000);
    printf("  滤波电容: %.3f uF\n", C_FILTER * 1e6);
    printf("  虚拟阻尼电阻: %.2f Ohm\n\n", R_DAMP);

    // 模拟运行10个控制周期
    for (int i = 0; i < 10; i++) {
        // 模拟ADC采样值（实际应用中由硬件提供）
        REG_WRITE(0x4004, (uint32_t)(2200 + rand() % 100));  // 220V左右波动
        REG_WRITE(0x4008, (uint32_t)(1000 + rand() % 50));   // 10A左右波动

        // 执行阻尼注入控制
        impedance_damping(&inverter);

        // 打印状态信息
        printf("周期 %d: V_out=%.2fV, I_out=%.2fA, I_damp=%.3fA, Duty=%.3f\n",
               i + 1,
               inverter.v_out_filtered,
               inverter.i_out_filtered,
               inverter.i_damp,
               inverter.duty_cycle);
    }

    printf("\n算法执行完成。\n");
    return 0;
}
