#include <stdio.h>
#include <math.h>

// 模拟三相电压/电流采样值结构体
typedef struct {
    double a;
    double b;
    double c;
} ThreePhase;

// 模拟dq坐标系下的量
typedef struct {
    double d;
    double q;
} DQ;

// 模拟PI控制器参数
typedef struct {
    double kp;
    double ki;
    double integral;
    double limit;
} PIController;

// 模拟PWM占空比输出
typedef struct {
    double u;
    double v;
    double w;
} PWMOutput;

// 宏定义：模拟系统参数
#define SAMPLE_TIME 0.0001  // 采样时间100us
#define PI 3.14159265358979323846
#define GRID_FREQ 50.0       // 电网频率50Hz

// 模拟三相电压传感器读取（实际需替换为ADC读取）
ThreePhase mock_read_voltage(void) {
    static double angle = 0.0;
    double theta = angle;
    angle += 2.0 * PI * GRID_FREQ * SAMPLE_TIME;
    if (angle > 2.0 * PI) angle -= 2.0 * PI;

    // 模拟不平衡负载：A相幅值1.0，B相0.8，C相1.2，并加入负序分量
    ThreePhase v;
    v.a = 1.0 * sin(theta) + 0.3 * sin(theta + PI/3);
    v.b = 0.8 * sin(theta - 2.0*PI/3) + 0.2 * sin(theta + PI/6);
    v.c = 1.2 * sin(theta + 2.0*PI/3) + 0.4 * sin(theta - PI/4);
    return v;
}

// Clarke变换：abc -> alpha-beta
void clarke_transform(ThreePhase abc, double *alpha, double *beta) {
    *alpha = (2.0/3.0) * (abc.a - 0.5*abc.b - 0.5*abc.c);
    *beta  = (2.0/3.0) * (0.86602540378*abc.b - 0.86602540378*abc.c);
}

// Park变换：alpha-beta -> dq (使用电网角度theta)
void park_transform(double alpha, double beta, double theta, DQ *dq) {
    dq->d = alpha * cos(theta) + beta * sin(theta);
    dq->q = -alpha * sin(theta) + beta * cos(theta);
}

// 反Park变换：dq -> alpha-beta
void inv_park_transform(DQ dq, double theta, double *alpha, double *beta) {
    *alpha = dq.d * cos(theta) - dq.q * sin(theta);
    *beta  = dq.d * sin(theta) + dq.q * cos(theta);
}

// 反Clarke变换：alpha-beta -> abc
ThreePhase inv_clarke_transform(double alpha, double beta) {
    ThreePhase abc;
    abc.a = alpha;
    abc.b = -0.5*alpha + 0.86602540378*beta;
    abc.c = -0.5*alpha - 0.86602540378*beta;
    return abc;
}

// PI控制器更新函数
double pi_controller(PIController *pi, double error) {
    pi->integral += error * SAMPLE_TIME;
    // 抗积分饱和
    if (pi->integral > pi->limit) pi->integral = pi->limit;
    if (pi->integral < -pi->limit) pi->integral = -pi->limit;
    double output = pi->kp * error + pi->ki * pi->integral;
    // 输出限幅
    if (output > pi->limit) output = pi->limit;
    if (output < -pi->limit) output = -pi->limit;
    return output;
}

// 负序补偿控制主函数
PWMOutput negative_sequence_compensation(ThreePhase v_abc, double theta) {
    // 1. 三相电压变换到dq坐标系
    double alpha, beta;
    clarke_transform(v_abc, &alpha, &beta);
    DQ v_dq;
    park_transform(alpha, beta, theta, &v_dq);

    // 2. 提取负序分量：在正序dq坐标系中，负序表现为2倍频波动
    // 这里简化处理：通过低通滤波提取直流分量（正序），然后相减得到负序
    static DQ v_dq_filtered = {0.0, 0.0};
    double alpha_lpf = 0.01; // 低通滤波系数
    v_dq_filtered.d = (1 - alpha_lpf) * v_dq_filtered.d + alpha_lpf * v_dq.d;
    v_dq_filtered.q = (1 - alpha_lpf) * v_dq_filtered.q + alpha_lpf * v_dq.q;

    DQ v_neg;
    v_neg.d = v_dq.d - v_dq_filtered.d;
    v_neg.q = v_dq.q - v_dq_filtered.q;

    // 3. 负序补偿PI控制：目标将负序分量控制到0
    static PIController pi_d = {0.5, 10.0, 0.0, 1.0};
    static PIController pi_q = {0.5, 10.0, 0.0, 1.0};
    double comp_d = pi_controller(&pi_d, -v_neg.d);
    double comp_q = pi_controller(&pi_q, -v_neg.q);

    // 4. 补偿量反变换到abc坐标系
    DQ comp_dq = {comp_d, comp_q};
    double comp_alpha, comp_beta;
    inv_park_transform(comp_dq, theta, &comp_alpha, &comp_beta);
    ThreePhase comp_abc = inv_clarke_transform(comp_alpha, comp_beta);

    // 5. 生成PWM占空比（假设直流母线电压为1.0，输出范围-1~1）
    PWMOutput pwm;
    pwm.u = comp_abc.a;
    pwm.v = comp_abc.b;
    pwm.w = comp_abc.c;
    return pwm;
}

int main() {
    printf("三相逆变器不平衡负载补偿（负序抑制）算法测试\n");
    printf("模拟运行10个采样周期...\n\n");

    double theta = 0.0;
    for (int i = 0; i < 10; i++) {
        // 模拟读取三相电压
        ThreePhase v_abc = mock_read_voltage();

        // 执行负序补偿
        PWMOutput pwm = negative_sequence_compensation(v_abc, theta);

        // 更新电网角度
        theta += 2.0 * PI * GRID_FREQ * SAMPLE_TIME;
        if (theta > 2.0 * PI) theta -= 2.0 * PI;

        // 打印结果
        printf("周期%d: 电压 A=%.3f B=%.3f C=%.3f | PWM U=%.3f V=%.3f W=%.3f\n",
               i+1, v_abc.a, v_abc.b, v_abc.c, pwm.u, pwm.v, pwm.w);
    }

    printf("\n测试完成。\n");
    return 0;
}
