#include <stdio.h>
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

// 模拟硬件寄存器定义
#define TIM_SAMPLING_FREQ 10000  // 10kHz采样率
#define GRID_FREQ 50             // 电网频率50Hz
#define SAMPLES_PER_CYCLE (TIM_SAMPLING_FREQ / GRID_FREQ) // 每周期200点

// 故障阈值定义
#define THD_THRESHOLD 0.05       // 总谐波畸变率阈值5%
#define VOLTAGE_DEVIATION_MAX 0.15 // 最大电压偏差15%
#define ZERO_CROSSING_WINDOW 5   // 过零检测窗口（采样点）

// 模拟ADC采样值（实际需替换为硬件读取）
typedef struct {
    float phase_a;
    float phase_b;
    float phase_c;
} three_phase_t;

// 故障状态枚举
typedef enum {
    FAULT_NONE = 0,
    FAULT_OVER_THD,
    FAULT_VOLTAGE_SAG,
    FAULT_VOLTAGE_SWELL,
    FAULT_DC_OFFSET,
    FAULT_HARMONIC_3RD,
    FAULT_HARMONIC_5TH,
    FAULT_HARMONIC_7TH
} fault_type_t;

// 诊断数据结构
typedef struct {
    float fundamental_amplitude;
    float thd;
    float dc_offset;
    float harmonic_3rd;
    float harmonic_5th;
    float harmonic_7th;
    float rms_voltage;
    fault_type_t active_fault;
    bool fault_detected;
} diagnostic_data_t;

// 全局诊断数据
static diagnostic_data_t g_diag = {0};

// 模拟ADC读取函数（实际需替换为硬件接口）
static three_phase_t mock_adc_read(void) {
    static uint32_t sample_count = 0;
    float t = (float)sample_count / TIM_SAMPLING_FREQ;
    float omega = 2.0f * M_PI * GRID_FREQ;

    // 生成含谐波的模拟波形（3次谐波5%，5次谐波3%，7次谐波2%）
    three_phase_t val;
    val.phase_a = 220.0f * sinf(omega * t) 
                + 11.0f * sinf(3.0f * omega * t) 
                + 6.6f * sinf(5.0f * omega * t) 
                + 4.4f * sinf(7.0f * omega * t);
    val.phase_b = 220.0f * sinf(omega * t - 2.0f * M_PI / 3.0f)
                + 11.0f * sinf(3.0f * omega * t - 2.0f * M_PI / 3.0f)
                + 6.6f * sinf(5.0f * omega * t - 2.0f * M_PI / 3.0f)
                + 4.4f * sinf(7.0f * omega * t - 2.0f * M_PI / 3.0f);
    val.phase_c = 220.0f * sinf(omega * t + 2.0f * M_PI / 3.0f)
                + 11.0f * sinf(3.0f * omega * t + 2.0f * M_PI / 3.0f)
                + 6.6f * sinf(5.0f * omega * t + 2.0f * M_PI / 3.0f)
                + 4.4f * sinf(7.0f * omega * t + 2.0f * M_PI / 3.0f);

    sample_count++;
    return val;
}

// 快速傅里叶变换（简化版，仅计算基波和指定谐波）
static void fft_analysis(const float* buffer, uint32_t size, float* fundamental, 
                         float* harmonic_3rd, float* harmonic_5th, float* harmonic_7th) {
    float sum_cos_fund = 0, sum_sin_fund = 0;
    float sum_cos_3rd = 0, sum_sin_3rd = 0;
    float sum_cos_5th = 0, sum_sin_5th = 0;
    float sum_cos_7th = 0, sum_sin_7th = 0;

    for (uint32_t i = 0; i < size; i++) {
        float angle = 2.0f * M_PI * i / size;
        sum_cos_fund += buffer[i] * cosf(angle);
        sum_sin_fund += buffer[i] * sinf(angle);
        sum_cos_3rd += buffer[i] * cosf(3.0f * angle);
        sum_sin_3rd += buffer[i] * sinf(3.0f * angle);
        sum_cos_5th += buffer[i] * cosf(5.0f * angle);
        sum_sin_5th += buffer[i] * sinf(5.0f * angle);
        sum_cos_7th += buffer[i] * cosf(7.0f * angle);
        sum_sin_7th += buffer[i] * sinf(7.0f * angle);
    }

    *fundamental = 2.0f * sqrtf(sum_cos_fund * sum_cos_fund + sum_sin_fund * sum_sin_fund) / size;
    *harmonic_3rd = 2.0f * sqrtf(sum_cos_3rd * sum_cos_3rd + sum_sin_3rd * sum_sin_3rd) / size;
    *harmonic_5th = 2.0f * sqrtf(sum_cos_5th * sum_cos_5th + sum_sin_5th * sum_sin_5th) / size;
    *harmonic_7th = 2.0f * sqrtf(sum_cos_7th * sum_cos_7th + sum_sin_7th * sum_sin_7th) / size;
}

// 计算总谐波畸变率
static float calculate_thd(float fundamental, float h3, float h5, float h7) {
    if (fabsf(fundamental) < 0.001f) return 0.0f;
    float harmonic_sum = h3 * h3 + h5 * h5 + h7 * h7;
    return sqrtf(harmonic_sum) / fundamental;
}

// 计算直流分量
static float calculate_dc_offset(const float* buffer, uint32_t size) {
    float sum = 0;
    for (uint32_t i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

// 计算有效值
static float calculate_rms(const float* buffer, uint32_t size) {
    float sum_sq = 0;
    for (uint32_t i = 0; i < size; i++) {
        sum_sq += buffer[i] * buffer[i];
    }
    return sqrtf(sum_sq / size);
}

// 故障诊断主函数
static void diagnose_fault(const float* buffer, uint32_t size) {
    float fundamental, h3, h5, h7;
    fft_analysis(buffer, size, &fundamental, &h3, &h5, &h7);

    g_diag.fundamental_amplitude = fundamental;
    g_diag.harmonic_3rd = h3;
    g_diag.harmonic_5th = h5;
    g_diag.harmonic_7th = h7;
    g_diag.thd = calculate_thd(fundamental, h3, h5, h7);
    g_diag.dc_offset = calculate_dc_offset(buffer, size);
    g_diag.rms_voltage = calculate_rms(buffer, size);

    // 故障判断逻辑
    g_diag.fault_detected = false;
    g_diag.active_fault = FAULT_NONE;

    // 1. 总谐波畸变率超标
    if (g_diag.thd > THD_THRESHOLD) {
        g_diag.fault_detected = true;
        g_diag.active_fault = FAULT_OVER_THD;
    }

    // 2. 电压偏差（相对于额定值220V）
    float voltage_deviation = fabsf(g_diag.rms_voltage - 220.0f) / 220.0f;
    if (voltage_deviation > VOLTAGE_DEVIATION_MAX) {
        g_diag.fault_detected = true;
        g_diag.active_fault = (g_diag.rms_voltage < 220.0f) ? FAULT_VOLTAGE_SAG : FAULT_VOLTAGE_SWELL;
    }

    // 3. 直流分量超标（阈值设为基波幅值的2%）
    if (fabsf(g_diag.dc_offset) > 0.02f * fundamental) {
        g_diag.fault_detected = true;
        g_diag.active_fault = FAULT_DC_OFFSET;
    }

    // 4. 特定谐波超标（阈值设为基波幅值的5%）
    if (h3 > 0.05f * fundamental) {
        g_diag.fault_detected = true;
        g_diag.active_fault = FAULT_HARMONIC_3RD;
    }
    if (h5 > 0.05f * fundamental) {
        g_diag.fault_detected = true;
        g_diag.active_fault = FAULT_HARMONIC_5TH;
    }
    if (h7 > 0.05f * fundamental) {
        g_diag.fault_detected = true;
        g_diag.active_fault = FAULT_HARMONIC_7TH;
    }
}

// 打印诊断结果
static void print_diagnostic_result(void) {
    printf("=== 逆变器输出电压诊断报告 ===\n");
    printf("基波幅值: %.2f V\n", g_diag.fundamental_amplitude);
    printf("有效值: %.2f V\n", g_diag.rms_voltage);
    printf("直流分量: %.3f V\n", g_diag.dc_offset);
    printf("总谐波畸变率(THD): %.2f%%\n", g_diag.thd * 100);
    printf("3次谐波: %.2f V (%.1f%%)\n", g_diag.harmonic_3rd, 
           (g_diag.harmonic_3rd / g_diag.fundamental_amplitude) * 100);
    printf("5次谐波: %.2f V (%.1f%%)\n", g_diag.harmonic_5th,
           (g_diag.harmonic_5th / g_diag.fundamental_amplitude) * 100);
    printf("7次谐波: %.2f V (%.1f%%)\n", g_diag.harmonic_7th,
           (g_diag.harmonic_7th / g_diag.fundamental_amplitude) * 100);

    if (g_diag.fault_detected) {
        printf("故障状态: 检测到故障!\n");
        switch (g_diag.active_fault) {
            case FAULT_OVER_THD: printf("故障类型: 总谐波畸变率超标\n"); break;
            case FAULT_VOLTAGE_SAG: printf("故障类型: 电压跌落\n"); break;
            case FAULT_VOLTAGE_SWELL: printf("故障类型: 电压骤升\n"); break;
            case FAULT_DC_OFFSET: printf("故障类型: 直流分量超标\n"); break;
            case FAULT_HARMONIC_3RD: printf("故障类型: 3次谐波超标\n"); break;
            case FAULT_HARMONIC_5TH: printf("故障类型: 5次谐波超标\n"); break;
            case FAULT_HARMONIC_7TH: printf("故障类型: 7次谐波超标\n"); break;
            default: printf("故障类型: 未知\n"); break;
        }
    } else {
        printf("故障状态: 正常\n");
    }
    printf("==============================\n\n");
}

int main(void) {
    printf("逆变器故障诊断系统启动...\n");
    printf("采样率: %d Hz, 电网频率: %d Hz\n", TIM_SAMPLING_FREQ, GRID_FREQ);
    printf("每周期采样点数: %d\n\n", SAMPLES_PER_CYCLE);

    // 分配采样缓冲区
    float sample_buffer[SAMPLES_PER_CYCLE];

    // 连续进行5次诊断
    for (int cycle = 0; cycle < 5; cycle++) {
        printf("第 %d 个电网周期诊断:\n", cycle + 1);

        // 采集一个完整周期的数据
        for (uint32_t i = 0; i < SAMPLES_PER_CYCLE; i++) {
            three_phase_t adc_val = mock_adc_read();
            sample_buffer[i] = adc_val.phase_a; // 仅分析A相
        }

        // 执行故障诊断
        diagnose_fault(sample_buffer, SAMPLES_PER_CYCLE);

        // 打印结果
        print_diagnostic_result();
    }

    printf("诊断完成。\n");
    return 0;
}
