#include <math.h>

// 模拟硬件寄存器定义 - 使用数组避免指针访问冲突
static uint32_t mock_registers[16] = {0};
#define REG_ADDR(idx) (mock_registers[idx])

#define PWM_TIMER_CR1      REG_ADDR(0)
#define PWM_TIMER_ARR      REG_ADDR(1)
#define PWM_TIMER_CCR1     REG_ADDR(2)
#define PWM_TIMER_CCR2     REG_ADDR(3)
#define PWM_TIMER_SR       REG_ADDR(4)
#define ADC_DR             ((uint16_t)REG_ADDR(5))
#define GPIO_ODR           ((uint16_t)REG_ADDR(6))

// 模拟寄存器位定义
#define TIM_CR1_CEN        (1 << 0)
#define TIM_SR_UIF         (1 << 0)
#define TIM_SR_CC1IF       (1 << 1)
#define TIM_SR_CC2IF       (1 << 2)

// 系统参数
#define SWITCHING_FREQ     20000
#define DEAD_TIME_NS       200
#define ZVS_THRESHOLD      0.5f
#define ZCS_THRESHOLD      0.1f

// 控制状态机
typedef enum {
    STATE_INIT,
    STATE_SOFT_START,
    STATE_NORMAL_OPERATION,
    STATE_FAULT
} ControlState;

// 软开关参数结构体
typedef struct {
    float input_voltage;
    float output_voltage;
    float inductor_current;
    float resonant_cap_voltage;
    float duty_cycle;
    float phase_shift;
    uint32_t dead_time_ticks;
    bool zvs_achieved;
    bool zcs_achieved;
} SoftSwitchingParams;

// 全局变量
static SoftSwitchingParams g_params = {0};
static ControlState g_state = STATE_INIT;
static uint32_t g_timer_ticks = 0;

// 模拟ADC读取
static float read_adc_voltage(void) {
    static float sim_val = 0.0f;
    sim_val += 0.01f;
    if (sim_val > 400.0f) sim_val = 0.0f;
    return sim_val;
}

// 模拟电流传感器
static float read_current_sensor(void) {
    static float sim_current = 0.0f;
    sim_current += 0.005f;
    if (sim_current > 10.0f) sim_current = -10.0f;
    return sim_current;
}

// 计算死区时间
static uint32_t calculate_dead_time_ticks(uint32_t timer_freq_hz) {
    if (timer_freq_hz == 0) return 0;
    return (uint32_t)((float)timer_freq_hz * DEAD_TIME_NS * 1e-9f);
}

// ZVS检测
static bool check_zvs_condition(float voltage_across_switch) {
    return (fabsf(voltage_across_switch) < ZVS_THRESHOLD);
}

// ZCS检测
static bool check_zcs_condition(float current_through_switch) {
    return (fabsf(current_through_switch) < ZCS_THRESHOLD);
}

// 软开关控制算法
static void soft_switching_control(void) {
    g_params.input_voltage = read_adc_voltage();
    g_params.inductor_current = read_current_sensor();
    g_params.resonant_cap_voltage = g_params.input_voltage * 0.5f;

    float voltage_ratio = 0.0f;
    if (g_params.input_voltage > 0.0f) {
        voltage_ratio = g_params.output_voltage / g_params.input_voltage;
    }
    if (voltage_ratio > 1.0f) voltage_ratio = 1.0f;
    if (voltage_ratio < 0.0f) voltage_ratio = 0.0f;
    g_params.duty_cycle = voltage_ratio;

    float phase_shift_rad = 0.0f;
    float denom = g_params.resonant_cap_voltage * 2.0f * (float)M_PI * SWITCHING_FREQ;
    if (fabsf(denom) > 1e-6f) {
        phase_shift_rad = atan2f(g_params.inductor_current, denom);
    }
    g_params.phase_shift = phase_shift_rad * 180.0f / (float)M_PI;

    uint32_t base_dead_time = calculate_dead_time_ticks(SWITCHING_FREQ);
    if (g_params.inductor_current > 5.0f) {
        g_params.dead_time_ticks = (uint32_t)((float)base_dead_time * 1.5f);
    } else {
        g_params.dead_time_ticks = base_dead_time;
    }

    g_params.zvs_achieved = check_zvs_condition(g_params.resonant_cap_voltage);
    g_params.zcs_achieved = check_zcs_condition(g_params.inductor_current);

    uint32_t period = 1000;
    uint32_t compare1 = (uint32_t)(period * g_params.duty_cycle);
    uint32_t compare2 = compare1 + g_params.dead_time_ticks;

    PWM_TIMER_ARR = period;
    PWM_TIMER_CCR1 = compare1;
    PWM_TIMER_CCR2 = compare2;

    PWM_TIMER_CR1 |= TIM_CR1_CEN;
}

// 状态机处理
static void state_machine_handler(void) {
    static float soft_start_duty = 0.0f;
    static uint32_t fault_counter = 0;

    switch (g_state) {
        case STATE_INIT:
            printf("System initializing...\n");
            g_params.output_voltage = 0.0f;
            g_params.duty_cycle = 0.0f;
            soft_start_duty = 0.0f;
            fault_counter = 0;
            g_state = STATE_SOFT_START;
            break;

        case STATE_SOFT_START:
            printf("Soft start in progress...\n");
            soft_start_duty += 0.01f;
            if (soft_start_duty > 0.5f) {
                soft_start_duty = 0.5f;
                g_state = STATE_NORMAL_OPERATION;
            }
            g_params.duty_cycle = soft_start_duty;
            g_params.output_voltage = g_params.input_voltage * g_params.duty_cycle;
            break;

        case STATE_NORMAL_OPERATION:
            soft_switching_control();

            if (g_params.input_voltage > 400.0f || 
                g_params.inductor_current > 10.0f) {
                printf("FAULT DETECTED! Entering protection mode.\n");
                g_state = STATE_FAULT;
            }
            break;

        case STATE_FAULT:
            printf("System in fault state. Resetting...\n");
            PWM_TIMER_CR1 &= ~TIM_CR1_CEN;
            PWM_TIMER_CCR1 = 0;
            PWM_TIMER_CCR2 = 0;

            fault_counter++;
            if (fault_counter > 100) {
                fault_counter = 0;
                g_state = STATE_INIT;
                printf("System reset complete.\n");
            }
            break;
    }
}

int main(void) {
    printf("=== Rectifier Soft-Switching (ZVS/ZCS) Control Demo ===\n");
    printf("System parameters:\n");
    printf("  Switching frequency: %d Hz\n", SWITCHING_FREQ);
    printf("  Dead time: %d ns\n", DEAD_TIME_NS);
    printf("  ZVS threshold: %.2f V\n", ZVS_THRESHOLD);
    printf("  ZCS threshold: %.2f A\n\n", ZCS_THRESHOLD);

    // 初始化模拟寄存器
    for (int i = 0; i < 16; i++) {
        mock_registers[i] = 0;
    }

    for (int cycle = 0; cycle < 20; cycle++) {
        printf("\n--- Control Cycle %d ---\n", cycle + 1);

        state_machine_handler();

        printf("State: %d\n", (int)g_state);
        printf("Input Voltage: %.2f V\n", g_params.input_voltage);
        printf("Output Voltage: %.2f V\n", g_params.output_voltage);
        printf("Inductor Current: %.2f A\n", g_params.inductor_current);
        printf("Duty Cycle: %.2f\n", g_params.duty_cycle);
        printf("Phase Shift: %.2f deg\n", g_params.phase_shift);
        printf("Dead Time Ticks: %lu\n", (unsigned long)g_params.dead_time_ticks);
        printf("ZVS Achieved: %s\n", g_params.zvs_achieved ? "YES" : "NO");
        printf("ZCS Achieved: %s\n", g_params.zcs_achieved ? "YES" : "NO");

        g_timer_ticks++;
    }

    printf("\n=== Control Demo Complete ===\n");
    return 0;
}
