#include <stdio.h>
#include <stdlib.h>

// 模拟PWM输出宏定义
#define PWM_MAX_DUTY 1000
#define PWM_MIN_DUTY 0

// 模拟ADC读取宏定义
#define ADC_VOLTAGE_CHANNEL 0
#define ADC_CURRENT_CHANNEL 1

// PID参数结构体
typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float output_min;
    float output_max;
} PID_Controller;

// 串级PID控制器结构体
typedef struct {
    PID_Controller voltage_pid;  // 外环：电压PID
    PID_Controller current_pid;  // 内环：电流PID
    float voltage_ref;           // 电压目标值
    float current_ref;           // 电流目标值（由电压环输出）
    float voltage_feedback;      // 电压反馈值
    float current_feedback;      // 电流反馈值
    float pwm_output;            // PWM输出占空比
} CascadePID;

// 初始化PID控制器
void PID_Init(PID_Controller *pid, float kp, float ki, float kd, float min, float max) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_min = min;
    pid->output_max = max;
}

// PID计算函数
float PID_Compute(PID_Controller *pid, float setpoint, float feedback) {
    float error = setpoint - feedback;
    float p_term = pid->kp * error;

    pid->integral += error;
    // 积分限幅
    if (pid->integral > pid->output_max / pid->ki) pid->integral = pid->output_max / pid->ki;
    if (pid->integral < pid->output_min / pid->ki) pid->integral = pid->output_min / pid->ki;
    float i_term = pid->ki * pid->integral;

    float d_term = pid->kd * (error - pid->prev_error);
    pid->prev_error = error;

    float output = p_term + i_term + d_term;

    // 输出限幅
    if (output > pid->output_max) output = pid->output_max;
    if (output < pid->output_min) output = pid->output_min;

    return output;
}

// 模拟读取电压反馈（单位：V）
float Read_Voltage_Feedback(void) {
    // 模拟ADC读取，返回0-24V之间的随机值
    return (float)(rand() % 2400) / 100.0f;
