    // 模拟PWM输出，限制在有效范围内
    if (duty > PWM_MAX_DUTY) duty = PWM_MAX_DUTY;
    if (duty < PWM_MIN_DUTY) duty = PWM_MIN_DUTY;
    printf("PWM输出占空比: %.2f\n", duty);
}

// 串级PID控制主函数
void CascadePID_Control(CascadePID *cascade) {
    // 读取反馈值
    cascade->voltage_feedback = Read_Voltage_Feedback();
    cascade->current_feedback = Read_Current_Feedback();

    // 外环：电压PID计算，输出作为内环的电流目标值
    cascade->current_ref = PID_Compute(&cascade->voltage_pid, cascade->voltage_ref, cascade->voltage_feedback);

