#define READ_REG(addr) mock_regs[(addr - 0x4000) / 4]
#define WRITE_REG(addr, val) mock_regs[(addr - 0x4000) / 4] = val

// 逆变器状态枚举
typedef enum {
    INVERTER_STATE_OFF = 0,
    INVERTER_STATE_STARTING,
    INVERTER_STATE_RUNNING,
    INVERTER_STATE_FAULT,
    INVERTER_STATE_STOPPING
} InverterState;

// 逆变器控制结构体
typedef struct {
    uint8_t id;                     // 逆变器ID (1或2)
    InverterState state;            // 当前状态
    uint32_t heartbeat_counter;     // 心跳计数
    bool is_master;                 // 是否为主机
    bool fault_detected;            // 故障标志
    uint32_t output_voltage;        // 输出电压 (模拟值)
    uint32_t output_current;        // 输出电流 (模拟值)
} Inverter;

// 冗余控制结构体
typedef struct {
    Inverter inv1;
    Inverter inv2;
    uint32_t switch_delay_ms;       // 切换延迟(ms)
    uint32_t heartbeat_timeout_ms;  // 心跳超时时间(ms)
    bool auto_switch_enabled;       // 自动切换使能
} RedundancyController;

// 初始化逆变器
void inverter_init(Inverter* inv, uint8_t id) {
    inv->id = id;
    inv->state = INVERTER_STATE_OFF;
    inv->heartbeat_counter = 0;
    inv->is_master = false;
    inv->fault_detected = false;
    inv->output_voltage = 0;
    inv->output_current = 0;
}

// 启动逆变器
void inverter_start(Inverter* inv) {
    if (inv->state == INVERTER_STATE_OFF) {
        inv->state = INVERTER_STATE_STARTING;
        printf("Inverter %d: Starting...\n", inv->id);
        // 模拟启动过程
        inv->state = INVERTER_STATE_RUNNING;
        inv->output_voltage = 220;
        inv->output_current = 10;
        printf("Inverter %d: Running (V=%d, I=%d)\n", inv->id, inv->output_voltage, inv->output_current);
    }
}

// 停止逆变器
void inverter_stop(Inverter* inv) {
    if (inv->state == INVERTER_STATE_RUNNING) {
        inv->state = INVERTER_STATE_STOPPING;
        printf("Inverter %d: Stopping...\n", inv->id);
        inv->output_voltage = 0;
        inv->output_current = 0;
        inv->state = INVERTER_STATE_OFF;
        printf("Inverter %d: Stopped\n", inv->id);
    }
}

// 检测逆变器故障
bool inverter_check_fault(Inverter* inv) {
    // 模拟故障检测：随机故障
    if (rand() % 100 < 5) {  // 5%概率故障
        inv->fault_detected = true;
        inv->state = INVERTER_STATE_FAULT;
        printf("Inverter %d: FAULT DETECTED!\n", inv->id);
        return true;
    }
    return false;
}

// 更新心跳
void inverter_update_heartbeat(Inverter* inv) {
    inv->heartbeat_counter++;
    if (inv->id == 1) {
        WRITE_REG(REG_HEARTBEAT_1, inv->heartbeat_counter);
    } else {
        WRITE_REG(REG_HEARTBEAT_2, inv->heartbeat_counter);
    }
}

// 读取心跳
uint32_t inverter_read_heartbeat(Inverter* inv) {
    if (inv->id == 1) {
        return READ_REG(REG_HEARTBEAT_1);
    } else {
        return READ_REG(REG_HEARTBEAT_2);
    }
}

// 主备切换逻辑
void redundancy_switch(RedundancyController* rc) {
    Inverter* master = NULL;
    Inverter* slave = NULL;

    // 确定当前主备关系
    if (rc->inv1.is_master) {
        master = &rc->inv1;
        slave = &rc->inv2;
    } else if (rc->inv2.is_master) {
        master = &rc->inv2;
        slave = &rc->inv1;
    } else {
        // 初始状态：无主机，设置逆变器1为主机
        printf("No master detected. Setting Inverter 1 as master.\n");
        rc->inv1.is_master = true;
        rc->inv2.is_master = false;
        inverter_start(&rc->inv1);
        return;
    }

    // 检查主机故障
    if (master->fault_detected || master->state == INVERTER_STATE_FAULT) {
        printf("Master inverter %d failed! Initiating switchover...\n", master->id);

        // 停止故障主机
        inverter_stop(master);
        master->is_master = false;

        // 启动备用机
        slave->is_master = true;
        inverter_start(slave);

        printf("Switchover complete: Inverter %d is now master.\n", slave->id);
        return;
    }

    // 检查心跳超时
    static uint32_t last_heartbeat_master = 0;
    uint32_t current_heartbeat = inverter_read_heartbeat(master);
    if (current_heartbeat == last_heartbeat_master) {
        // 心跳未更新，可能死机
        printf("Master inverter %d heartbeat timeout! Initiating switchover...\n", master->id);

        inverter_stop(master);
        master->is_master = false;
        master->fault_detected = true;

        slave->is_master = true;
        inverter_start(slave);

        printf("Switchover complete: Inverter %d is now master.\n", slave->id);
    }
    last_heartbeat_master = current_heartbeat;
}

// 主控制循环
void redundancy_control_loop(RedundancyController* rc) {
    // 更新心跳
    inverter_update_heartbeat(&rc->inv1);
    inverter_update_heartbeat(&rc->inv2);

    // 检测故障
    inverter_check_fault(&rc->inv1);
    inverter_check_fault(&rc->inv2);

    // 执行切换逻辑
    if (rc->auto_switch_enabled) {
        redundancy_switch(rc);
    }

    // 打印状态
    printf("Status: Inv1=%s(%s), Inv2=%s(%s)\n",
           rc->inv1.state == INVERTER_STATE_RUNNING ? "RUN" : "STOP",
           rc->inv1.is_master ? "MASTER" : "SLAVE",
           rc->inv2.state == INVERTER_STATE_RUNNING ? "RUN" : "STOP",
           rc->inv2.is_master ? "MASTER" : "SLAVE");
}

