#define VREF 220.0f

// 模拟寄存器宏定义
#define PWM_PERIOD 1000
#define DUTY_MAX 0.95f
#define DUTY_MIN 0.05f

// 模拟PWM寄存器地址（使用静态变量避免指针问题）
