static unsigned int mock_pwm_reg3 = 0;

// 三相电压结构体
typedef struct {
    float ua;
    float ub;
    float uc;
} ThreePhaseVoltage;

// 三相电流结构体
typedef struct {
    float ia;
    float ib;
    float ic;
} ThreePhaseCurrent;

// 控制器状态
typedef struct {
    float integral_a;
    float integral_b;
    float integral_c;
} ControllerState;

// 全局变量
static ControllerState g_controller = {0};
static float g_theta = 0.0f;
static float g_phase = 0.0f;

// 模拟读取ADC值（返回三相电流）
ThreePhaseCurrent mock_read_adc(void) {
    g_phase += 2.0f * PI * GRID_FREQ / SAMPLE_FREQ;
    if (g_phase > 2.0f * PI) g_phase -= 2.0f * PI;

    ThreePhaseCurrent current;
    current.ia = 10.0f * sinf(g_phase) + 0.5f * sinf(3.0f * g_phase);
    current.ib = 10.0f * sinf(g_phase - 2.0f * PI / 3.0f) + 0.5f * sinf(3.0f * g_phase - 2.0f * PI / 3.0f);
    current.ic = 10.0f * sinf(g_phase + 2.0f * PI / 3.0f) + 0.5f * sinf(3.0f * g_phase + 2.0f * PI / 3.0f);
    return current;
}

// 生成三相参考电压（平衡正弦波）
ThreePhaseVoltage generate_reference(void) {
    g_theta += 2.0f * PI * GRID_FREQ / SAMPLE_FREQ;
    if (g_theta > 2.0f * PI) g_theta -= 2.0f * PI;

    ThreePhaseVoltage ref;
    float vpeak = VREF * sqrtf(2.0f);
    ref.ua = vpeak * sinf(g_theta);
    ref.ub = vpeak * sinf(g_theta - 2.0f * PI / 3.0f);
    ref.uc = vpeak * sinf(g_theta + 2.0f * PI / 3.0f);
    return ref;
}

// PI控制器（单相）
float pi_controller(float error, float *integral, float kp, float ki) {
    *integral += error * (1.0f / SAMPLE_FREQ);
    // 抗积分饱和
    if (*integral > 100.0f) *integral = 100.0f;
    if (*integral < -100.0f) *integral = -100.0f;

    float output = kp * error + ki * (*integral);
    return output;
}

// 三相电压平衡控制主函数
void voltage_balance_control(void) {
    // 1. 读取三相电流反馈
    ThreePhaseCurrent feedback = mock_read_adc();

    // 2. 生成三相参考电压
    ThreePhaseVoltage reference = generate_reference();

    // 3. 计算误差
    float error_a = reference.ua - feedback.ia * 0.5f;
    float error_b = reference.ub - feedback.ib * 0.5f;
    float error_c = reference.uc - feedback.ic * 0.5f;

    // 4. PI控制计算占空比
    float kp = 0.5f;
    float ki = 10.0f;

    float duty_a = pi_controller(error_a, &g_controller.integral_a, kp, ki);
    float duty_b = pi_controller(error_b, &g_controller.integral_b, kp, ki);
    float duty_c = pi_controller(error_c, &g_controller.integral_c, kp, ki);

    // 5. 限幅
    if (duty_a > DUTY_MAX) duty_a = DUTY_MAX;
    if (duty_a < DUTY_MIN) duty_a = DUTY_MIN;
    if (duty_b > DUTY_MAX) duty_b = DUTY_MAX;
    if (duty_b < DUTY_MIN) duty_b = DUTY_MIN;
    if (duty_c > DUTY_MAX) duty_c = DUTY_MAX;
    if (duty_c < DUTY_MIN) duty_c = DUTY_MIN;

    // 6. 写入PWM寄存器（使用静态变量模拟）
    mock_pwm_reg1 = (unsigned int)(duty_a * PWM_PERIOD);
    mock_pwm_reg2 = (unsigned int)(duty_b * PWM_PERIOD);
    mock_pwm_reg3 = (unsigned int)(duty_c * PWM_PERIOD);
}

// 主函数
int main(void) {
    printf("三相逆变器相电压平衡控制系统启动...\n");
    printf("参考电压有效值: %.1fV, 直流母线电压: %.1fV\n", VREF, VDC);
    printf("采样频率: %.0fHz, 电网频率: %.0fHz\n\n", SAMPLE_FREQ, GRID_FREQ);

